programs.sol:
"""Detect capital R, with weaker responses to r and short R abbreviations.

R is strongest at a document start and in the microRNA prefix miR. Recent
capital-heavy spelling reduces it. RNA-related abbreviations also respond;
long ordinary words containing R usually do not. Cyrillic er, fullwidth R,
and the real-number symbol are treated separately. These are spelling rules,
not a claim that the component recognizes a document's scientific topic.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', ''
    else:
        previous, recent = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    letters = ''.join(c for c in word if c.isalpha())
    spaced = token.startswith(' ')
    value = 0.001

    if word == 'R':
        last = previous[-1:]
        capitals = [c.isupper() for c in recent if c.isalpha()]
        capital_fraction = sum(capitals) / max(len(capitals), 1)
        value = 1.78 - 0.28 * spaced - 0.27 * capital_fraction
        if not previous:
            value = 2.97 if not spaced else 2.02
        elif last.isupper():
            value -= 0.73
        elif last.isdigit():
            value -= 0.28
        elif last.isspace():
            value -= 0.18
        elif last.islower() and len(previous.strip()) <= 2:
            value += 0.18 if spaced else 0.06
        if not spaced and previous.strip().lower() == 'mi':
            value += 1.56  # R in the conventional microRNA prefix miR.
    elif letters == 'R':
        value = 1.52 if word.startswith('/') else 1.02
    elif letters == 'r':
        value = 0.19 if word == 'r' else 0.30
    elif word in {'RN', 'RNA'}:
        value = 1.22 if spaced else 1.78 if word == 'RN' else 2.08
    elif word == 'mRNA':
        value = 0.66
    elif word in {'PCR', 'RT'}:  # PCR and reverse transcription.
        value = 0.80 if word == 'PCR' else 0.99 if spaced else 0.81
    elif 'R' in letters and letters.isupper():
        if len(letters) == 2:
            value = 0.48
            r_then_vowel = letters.startswith('R') and letters[1] in 'AEIOU'
            if letters == 'OR':
                value = 0.05  # Also an ordinary English function word.
            elif not spaced and (letters.endswith(('ER', 'UR')) or r_then_vowel):
                value = 0.10  # Common vowel/R fragments rather than initials.
            elif letters.endswith('R') and letters[0] in 'MN':
                value = 0.98  # Nasal-consonant/R initials.
            elif r_then_vowel:
                value = 0.34
        elif len(letters) == 3:
            value = 0.12
    elif letters.startswith('R'):
        value = 0.22 if len(letters) == 2 else 0.08 if len(letters) == 3 else 0.025
    elif letters == 'Р':  # Cyrillic er, the Cyrillic counterpart of R.
        value = 0.52 if spaced else 0.36
    elif letters == 'р':
        value = 0.20 if spaced else -0.02
    elif word == 'Ｒ':
        value = 0.65  # Fullwidth capital R.
    elif word == 'ℝ':
        value = 1.80  # Double-struck R denoting the real numbers.

    return (doc, token, (recent + token)[-80:]), float(value)

programs.haiku:
"""Attention-and-focus preposition detector for layers.0.mlp.down_proj:321.

The component fires on the preposition that completes a phrase of directing attention,
focus, devotion, investment or allocation: "focus ON", "attention TO", "dedicated TO",
"invested IN", "assigned TO", "spend ... ON". It is strongest when the preposition follows
a word of focusing or devoting, and weaker for prepositions after words of placing,
directing or returning. The nouns "attention" and "focus" themselves also fire.
Everything else is near zero.
"""

PREPOSITIONS = {"to", "on", "in", "into", "onto", "upon", "towards", "toward", "against", "at"}
FOCUS_WORDS = {
    "focus", "focuses", "focused", "focusing", "concentrate", "concentrates",
    "concentrated", "concentrating", "attention", "emphasis", "spend", "spends",
    "spent", "spending", "dedicated", "dedicate", "dedicates", "dedicating",
    "dedication", "devoted", "devote", "devotes", "devotion", "commit", "commits",
    "committed", "commitment",
}
INVEST_WORDS = {
    "invest", "invests", "invested", "investing", "investment", "investments",
    "allocated", "allocate", "assigned", "assign", "allotted", "given", "give",
    "gave", "granted", "funds", "money", "resources", "budget",
}
DIRECT_WORDS = {
    "directed", "direct", "shift", "shifted", "shifts", "turned", "turn", "pointing",
    "pointed", "point", "put", "placed", "place", "moved", "moves", "move",
    "redirected", "relocated", "glued", "locked", "applied", "apply", "attached",
    "attach", "transferred", "transfer", "returned", "return", "referred", "refer",
    "refers", "reference", "contribute", "contributed", "contributes", "contribution",
    "access", "exposure", "belongs", "belong", "interested", "working", "work",
    "worked", "works", "rely", "relied", "depends", "depend", "reliance", "sensitive",
}
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        before = ""
    else:
        before = prefix.token_strings[-2].strip().lower()
    if word in PREPOSITIONS:
        if before in FOCUS_WORDS:
            value = 2.8
        elif before in INVEST_WORDS:
            value = 1.6
        elif before in DIRECT_WORDS:
            value = 0.5
        else:
            value = 0.0
    elif word in ("attention", "focus", "emphasis"):
        value = 1.2
    elif word == "time" and before in ("spend", "spent", "spending"):
        value = 1.6
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Predict restrained positive pulses on 'to' and 'on', recurring firing contexts."""
READS = ()

PULSES = {"to": 0.05, "on": 0.07}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return None, PULSES.get(word, 0.0)

"""Estimate activation from the current token piece's ending alone.

Recognized fragments are mostly German adjective endings (-lich, -ig, -bar,
-keit), plus a few English and other language endings. Space-starting and
unrecognized pieces are predicted as zero; estimates are deliberately small.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    # A leading blank usually marks a new word, not an ending inside a word.
    if not token or token[0].isspace():
        return None, 0.0
    piece = token.casefold()

    if piece.endswith((
        "lichkeit", "lichkeiten", "lich", "liche", "lichen", "licher", "liches"
    )):
        value = -3.0
    elif piece.endswith(("igkeit", "keiten", "keit")):
        value = -2.5
    elif piece.endswith(("bar", "bare", "baren", "bares")):
        value = -4.0
    elif piece.endswith(("ig", "ige", "igen", "iger", "iges")):
        value = -4.0
    elif piece.endswith(("isch", "ische", "ischen", "ischer", "isches")):
        value = -1.0
    elif piece.endswith(("ung", "ungen")):
        value = -1.0
    elif piece.endswith(("end", "ende", "enden")):
        value = -2.0
    elif piece.endswith(("able", "ably", "less")):
        value = -0.5
    elif piece.endswith("ksam"):
        value = -2.2
    elif piece.endswith(("ivi", "ingen", "ских", "но", "적으로", "stoff")):
        # A few other recognizable endings and compound pieces have a smaller
        # response.
        value = -0.7
    else:
        value = 0.0
    # The feature is sparse; a conservative scale avoids overpredicting its
    # response on every token that merely looks like an ending.
    return None, 0.29 * value

programs.sol:
"""A negative 'bl' detector with semantic spillover to blankness and blindness.

Bare letter fragments and blank/blind words are strongest. Most other bl-word
families are weaker; common black/block/blood/blog words are particularly weak.
The piece following a token ending in 'bl' gets a small negative echo.
Also recognize a few Chinese translations and non-Latin spellings of the bl sound. Otherwise zero.
The separate word 'able' is stronger after several forms of 'be' and 'not'
than after 'be' itself. Only the preceding token is remembered, reset at each document
boundary. This leaves unrelated weak lexical responses unmodeled.
"""
READS = ()


def lexical_value(raw):
    s = raw.strip()
    w = s.lower().lstrip(".-_('/\"")
    boundary = raw[:1].isspace()
    if w == 'bl':
        if s.startswith('-'):
            return -6.1
        if s == 'BL' and boundary:
            return -3.6
        return -4.3
    if w in ('blank', 'blanks', 'blind', 'blindness'):
        return -4.7
    if w.startswith(('blind', 'blur', 'blam')):
        return -3.0
    if w in ('ble', 'bles', 'bling', 'ably', 'ables'):
        if w == 'ble':
            return -1.8 if boundary else -1.1
        return -0.3
    if w.startswith('bl'):
        if w.startswith(('black', 'bloc', 'blood', 'blog')):
            return -0.2
        if w.startswith(('blo', 'blick', 'bleib', 'bless', 'blush')):
            return -0.5
        if w.startswith(('blend', 'blot', 'bladd', 'blair', 'blond')):
            return -2.0
        if w in ('bla', 'blas'):
            return -2.8
        return -1.2
    if w == 'able':
        return -0.75 if boundary else -0.15
    if w == 'unable' or w.startswith('oblig'):
        return -0.6
    if w in ('abl', 'obl', 'ibl', 'dbl'):
        return -2.3
    if w in ('ablo', 'ibli', 'bibli', 'obliv'):
        return -1.3
    if w.startswith('бл'):
        return -1.5 if len(w) <= 3 else -0.6
    if w in ('ブル', '블'):
        return -1.7
    if w == 'بل':
        return -0.3 if boundary else -0.8
    # Chinese: blue, blind, blank, blurred and blowing.
    if w in ('蓝', '藍', '模糊', '吹'):
        return -1.8
    if w == '盲':
        return -6.2
    if w in ('瞎', '盲目', '空白'):
        return -2.5
    if w in ('蓝天', '藍天', '蓝色', '藍色', '糊', '蒙'):
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    word, prior = raw.strip().lower(), previous.strip().lower()
    value = lexical_value(raw)
    if word == 'bl' and prior == 'pro' and not raw[:1].isspace():
        value = -1.7  # A split beginning of "problem" is weaker.
    if word == 'able' and raw[:1].isspace():
        if prior == 'be':
            value = -0.52
        elif prior in ('is', 'was', 'are', 'were', 'am', 'been', 'being', 'not'):
            value = -0.98
    if prior.endswith('bl') and raw[:1].isalpha():
        joined = prior + word
        if joined.endswith(('blank', 'blanks')):
            value = -4.0
        elif 'blur' in joined:
            value -= 1.8
        else:
            value -= 0.75
    return (doc, raw), float(value)

programs.haiku:
"""Word-start 'bl' detector (negative).

The component pushes the residual stream in a negative direction on tokens that
spell the letters "bl" at the start of a word piece, and it is strongest when the
piece is a bare fragment of a longer word, as in "Un|bl|anching" or "sand|bl|asted",
and on "blind" (double-blind) and "blank". Ordinary whole words beginning "bl" are
moderately negative (blue, blend, blur, blast), and common words like black, block,
blood are barely affected. Pieces that continue a split "bl" word (-asts, -anch,
-azed) are also moderately negative. Everywhere else it is near zero.
"""

READS = ()

FRAGMENT = {"bl", "-bl", ".bl"}          # bare "bl" pieces, with punctuation
BLIND_BLANK = {"blind", "blank"}
COMMON_BL = {"black", "block", "blood", "blog", "blocks", "blogs", "blocked",
             "blocking", "bless", "blessed", "blessing", "blessings", "bloom"}
BL_LIKE = {"able", "ble", "obl", "abl", "ablo", "蓝", "藍", "бл"}


def _word(s):
    return s.strip(" -.\"'(").lower()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = _word(token)
    if word in FRAGMENT or token.strip() in FRAGMENT:
        value = -4.4
    elif word in BLIND_BLANK:
        value = -4.8
    elif word.startswith("bl"):
        value = -0.2 if word in COMMON_BL else -1.2
    elif word in BL_LIKE:
        value = -1.0
    elif (len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
          and _word(prefix.token_strings[-2]) in FRAGMENT and not token.startswith(" ")):
        value = -1.0
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Approximate a mixed detector for web/software names and text conventions.

Read only the current token's spelling. Return positive values for a closing
thinking tag, URL/scope/annotation syntax, selected symbols and file suffixes,
recognized software or brand names, and compound API identifiers. Length and
capitalization adjust the latter responses. All other tokens return zero.

The rules cover prominent positive responses, not the component's many
word-specific, negative, or contextual responses. No state is kept.
"""
import re

READS = ()

BRANDS = set('''
google github microsoft facebook amazon apple samsung instagram netflix
snapchat twitter youtube telegram reddit whatsapp linkedin pinterest spotify
adobe ibm aws hbo disney nintendo playstation xbox etsy shopify icloud intel
chrome firefox patreon wikipedia
'''.split())

PACKAGES = set('''
springframework androidx firebase unsplash minecraft junit maven vaadin gson
lombok okhttp rxjs javafx hibernate gstatic githubusercontent slf4j testng
svelte cucumber jackson
'''.split())

TOOLS = set('''
eslint tslint vscode asyncio tqdm shutil pathlib tkinter serde graphql
illuminate laravel glfw imgui beautifulsoup tensorflow scipy sklearn seaborn
iostream strconv
'''.split())

FILE_EXTENSIONS = {
    '.ts': 0.78, '.rs': 0.58, '.json': 0.73, '.md': 0.38,
    '.js': 0.25, '.yaml': 0.35, '.yml': 0.47, '.vue': 0.68,
    '.csv': 0.47, '.hpp': 0.59, '.jpg': 0.28, '.html': 0.20,
    '.txt': 0.16, '.pdf': 0.14,
}


MODERATE_TOOLS = set('''
numpy pandas torch keras matplotlib django pygame urllib unittest setuptools
pytest apache npm yarn cargo
'''.split())

CHINESE_BRANDS = set('三星 腾讯 京东 百度 豆瓣 苹果'.split())


def token_value(raw):
    s = raw.strip()
    lower = s.lower()
    word = lower.lstrip('./\\_-(')
    if s == '</think>':
        return 1.29
    if s == '().__':
        return 1.20
    if s in {'::', '::$'}:
        return 0.85
    if '::' in s:
        return 0.55
    if s in {'✓', '✔', '✅', '✝', '✭'}:
        return 0.66
    if s == '❌':
        return 0.97
    if s in {'http', 'https'}:
        return 1.05
    if lower in {'http', 'https'}:
        return 0.59
    if s == '://':
        return 0.46
    if word == 'http':
        return 0.78
    if s in {'(@', '{@', '"@'}:
        return 0.40
    if s == ',@':
        return 0.18
    if s in {'©', 'ˈ', '⊢'}:
        return {'©': 0.38, 'ˈ': 0.60, '⊢': 0.28}[s]
    if s == '@':
        return 0.39 if raw[:1].isspace() else 0.56
    if s.startswith('@') and s[1:].isalpha():
        return 0.48
    if s == 'www' and raw[:1].isspace():
        return 0.73
    if s in FILE_EXTENSIONS:
        return FILE_EXTENSIONS[s]
    if s in {'.com', '.org', '.net', '.edu', '.gov', '.io'}:
        return 0.22
    if s in CHINESE_BRANDS:
        return 0.80
    if word in BRANDS:
        value = 0.61 + 0.36 * (len(word) >= 9)
        if s.startswith('.') and word != 'github':
            value += 0.30
        return value
    if word in PACKAGES and (s == lower or word != lower):
        if s.startswith('.') or word != lower:
            return 1.10 + 0.40 * (len(word) >= 12)
        return 0.90
    if word in TOOLS:
        return 0.90
    if word in MODERATE_TOOLS:
        return 0.35
    if raw in {'LICENSE', 'README'}:
        return 0.29
    if word == 'json':
        return 0.60
    if word in {'yaml', 'csv', 'xlsx'}:
        return 0.40
    if lower == 'typescript':
        return 0.65
    if s in {'_ts', '/ts'}:
        return 0.25
    if s == 'ts':
        return 0.23 if raw[:1].isspace() else 0.0
    if word in {'docs', 'repo'} and s == word and not raw[:1].isspace():
        return 0.55
    if re.match(r'^(toBe|toHave|toMatch|assertThat|isEqualTo)', s):
        return 0.70 + 0.03 * max(0, len(s) - 7)
    identifier = s.lstrip('.:(')
    if identifier.isascii() and identifier.isalpha():
        if (identifier != 'Exception' and len(identifier) > 7
                and identifier.endswith(('Error', 'Exception'))):
            return 0.35 + 0.04 * max(0, len(identifier) - 8)
        if re.search(r'[a-z][A-Z]|[A-Z]{2}[a-z]', identifier):
            value = 0.20 + 0.035 * max(0, len(identifier) - 5)
            if len(identifier) >= 8 and sum(c.isupper() for c in identifier) >= 3:
                value += 0.40
            return value
        if s.startswith('.') and len(identifier) >= 12:
            return 0.50
    return 0.0


def step(carry, prefix, upstream):
    return None, float(token_value(prefix.token_strings[-1]))

"""Comma punctuation with adaptation to nearby commas.

Isolated commas give a negative response. Another comma a few tokens earlier
weakens that response, sometimes reversing its sign. East Asian commas have
different strengths; the enumeration mark after a digit is not a prose comma.
Comma tokens fused with quotes, brackets, or newlines are handled separately.
"""
READS = ()
COMMAS = ',，、،'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, last_comma, previous = 0, -1000, ''
    else:
        _, position, last_comma, previous = carry
    token = prefix.token_strings[-1]
    text = token.strip()
    distance = position - last_comma
    early = 1.0 / (1.0 + position / 20.0)
    value = -0.007

    if text == ',' and '\n' not in token:
        recovery = 1.0 / (1.0 + ((distance - 1) / 4.5) ** 2)
        value = -0.557 + 0.70 * recovery - 0.18 * early
        if last_comma < 0:
            value -= 0.025
        if token.startswith(' '):
            value -= 0.115
        if previous.strip().isdigit():
            value += 0.024
        if previous.strip() in ('(', ')', '[', ']', '{', '}'):
            value += 0.09
        if position == 0:
            value = 0.065
        elif position == 1:
            value += 0.34
    elif text == '，' and '\n' not in token:
        recovery = 1.0 / (1.0 + (max(distance - 1, 0) / 3.0) ** 0.8)
        value = -0.71 + 0.79 * recovery - 0.12 * early
        if previous.strip().isdigit():
            value += 0.07
        if position == 0:
            value = -0.03
        elif position == 1:
            value += 0.18
    elif text == '、':
        recovery = 1.0 / (1.0 + max(distance - 1, 0) / 12.0)
        value = -1.34 + 0.55 * recovery
        if last_comma < 0:
            value += 0.115
        if previous.strip().isdigit():
            value += 1.14
        if position <= 1:
            value += 0.35
    elif text == '،':
        value = -0.25
    elif any(c in token for c in COMMAS):
        # A comma embedded in a larger token is not equivalent to a bare comma.
        if '\n' in token:
            value = 0.07 if text.startswith(',') else 0.04
        elif text.endswith((',', '，', '、')):
            before = text[:-1]
            if before and all(c in ')]}»`$%' for c in before):
                value = -0.25 + 0.18 / (1.0 + distance / 5.0)
            else:
                value = 0.03
        else:
            value = 0.06

    if any(c in token for c in COMMAS):
        last_comma = position
    return (doc, position + 1, last_comma, token), float(value)

programs.luna:
"""Recognize isolated comma tokens, which this component strongly suppresses."""
