_COMMA_EFFECT = {
    ",": -0.55,
    "，": -0.73,
    "、": -1.10,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    return None, _COMMA_EFFECT.get(token, -0.02)

programs.sol:
"""A token-local detector of 'block' and related structural vocabulary.

Blocks give the largest negative response, in prose, code identifiers, and
Chinese. Inflected verbs, spelling fragments, and words for containers,
modules and building materials give smaller responses. A few short phrases
also matter: 'block of' stays negative; 'look on/for/at' becomes positive.
A Chinese '块' following a number has a stronger response. State resets
at document boundaries. These are spelling and phrase rules, not semantics.
"""
READS = ()
LOOK_FORMS = frozenset(('look', 'looks', 'looked', 'looking'))


def word_of(token):
    return token.strip().lstrip('._/({[-:<').lower()


def response(token):
    text = token.strip()
    word = word_of(token)
    spaced = token[:1].isspace()
    if word in ('block', 'blocks'):
        if text.startswith(('(', '[', '<')):
            value = -4.5
        elif text.startswith('.'):
            value = -5.4
        elif spaced:
            value = -6.0 if text[:1].isupper() else -5.6
        else:
            value = -6.6 if text[:1].isupper() else -6.0
        return value + (0.3 if word == 'blocks' else 0.0)
    # Chinese: block/piece, slab and module spellings.
    if text in ('块', '一块', '这块', '那块'):
        return -6.6
    if text in ('塊', '一塊'):
        return -5.5
    if text in ('模块', '板块'):
        return -2.4
    if text == '区块':
        return -3.5
    if word == 'blocksize':
        return -3.0
    if word in ('blockchain', 'blocker', 'blockers', 'blockade'):
        return -0.9
    if word == 'blocked':
        return -2.3 if spaced else -1.9
    if word == 'blocking':
        return -1.7
    # Short spellings of block and its French/Spanish/Russian relatives.
    if word == 'blo':
        return -1.4
    if word in ('bloc', 'bloque', 'блок'):
        return -2.6 if spaced and text[:1].islower() else -1.8
    if word == 'бл':
        return -2.5 if spaced else -0.5
    if word == 'ロック':
        return -2.4
    if word in ('lock', 'locks', 'clock', 'clocks'):
        return -0.8 if spaced or text[:1] in '._/' else -1.4
    if word in ('locked', 'unlock', 'unlocked', 'locking'):
        return -0.9 if text == 'Unlock' else -0.45
    if word in ('module', 'modules'):
        if text.startswith('/modules'):
            return -2.0
        if text.startswith('_') or word == 'modules':
            return -1.1
        return -1.5
    if word == 'modular':
        return -0.65
    if word in ('chunk', 'chunks'):
        return -1.8
    if word in ('box', 'boxes', 'boxed', 'boxing', '盒子'):
        return -0.9 if word == 'box' else -0.7
    if word in ('node', 'nodes'):
        return -0.2 if word == 'nodes' else -0.45
    if word in ('frame', 'frames', '框'):
        return -0.7 if text.startswith('.') or text == '框' else -0.25
    if word in ('brick', 'bricks', 'tile', 'tiles', 'wooden', '砖', '瓷砖', '木'):
        return -0.7
    if word in ('stone', 'stones', 'crates', 'slide', 'slides', '锁'):
        return -0.35
    if word in ('cell', 'cells', 'piece', 'pieces', 'section', '部分'):
        return -0.25
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = older = ''
    if carry is not None and carry[0] == document:
        _, previous, older = carry
    token = prefix.token_strings[-1]
    word = word_of(token)
    value = response(token)
    if word == 'of':
        if previous in ('block', 'blocks'):
            value = -2.1
        elif previous in ('chunk', 'chunks'):
            value = -0.9
        elif previous in ('piece', 'pieces'):
            value = -0.3
    if previous in LOOK_FORMS or older in LOOK_FORMS:
        if word in ('on', 'upon'):
            value = 1.0 if previous in LOOK_FORMS else 0.7
        elif word == 'for':
            value = 0.45 if previous in LOOK_FORMS else 0.15
        elif word in ('at', 'in', 'to'):
            value = 0.25 if previous in LOOK_FORMS else 0.1
    if word == 'to' and previous == 'forward' and older in LOOK_FORMS:
        value = 0.3
    if previous == 'бл' and word in ('ок', 'ока', 'оки'):
        value = -2.1
    if word == '块':
        number = any(c.isdigit() or c in '一二三四五六七八九十百千万亿两几'
                     for c in previous)
        value = -7.2 if number else -6.2
    return (document, word, previous), float(value)

programs.luna:
"""A small lexical sketch of the component's negative token cues.

It gives the largest response to tokens containing 'block', and smaller
responses to lock/box/module/chunk, frame, or part/brick/flow/node words
(and a few Chinese counterparts). It uses only the current token, so it misses
context and other triggers.
"""
READS = ()

STRONG = ("lock", "box", "module", "chunk", "盒子")
WEAK = ("part", "brick", "flow", "砖", "部分", "node")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if "block" in word:
        value = -5.5
    elif any(term in word for term in STRONG):
        value = -1.3
    elif "frame" in word:
        value = -0.85
    elif any(term in word for term in WEAK):
        value = -0.65
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""A lexical equality/comparison signal, not a test of mathematical truth.

'Equal' is strongest. Equality inflections, equations, comparison signs,
sameness, 'what', and quality words give smaller positive responses.
Remember one token for 'equal to', 'less/greater than', and split words or
LaTeX commands. Unrecognized text gives zero; documents reset the memory.
"""
READS = ()

EQUALITY_WORDS = {
    'equal': 7.0, 'equals': 5.2, 'eq': 2.4, 'equality': 3.1,
    'equally': 2.4, 'unequal': 4.2, 'inequality': 2.0,
    'inequalities': 2.7, 'equation': 1.45, 'equations': 1.2,
    'partialeq': 3.3, 'equivalent': 0.6, 'equivalence': 0.6,
    'equiv': 0.6, 'equity': 0.9, 'equilibrium': 0.9,
}
RELATED_WORDS = {
    'what': 0.8, 'same': 0.7, 'better': 0.67, 'quality': 0.55,
    'less': 0.33, 'different': 0.26, 'greater': 0.5,
}
# Words or roots for equality, evenness, or sameness in other languages.
TRANSLATIONS = {
    '等': 1.7, '等于': 3.8, '平等': 2.2, '均': 0.6,
    '同': 0.5, '同一': 0.6, '同样': 0.5, '同じ': 0.85,
    'рав': 3.0, 'равно': 1.7, 'gleich': 0.9,
    'igual': 1.6, 'eş': 0.8, 'bằng': 0.75, '등': 1.2,
}
OPERATORS = {
    '!=': 0.33, '<=': 0.45, '>=': 0.33,
    '≠': 0.58, '≤': 0.51, '≥': 0.37,
}


def normalize(token):
    return token.strip().lstrip('._').lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    s, word, prev = raw.strip(), normalize(raw), normalize(previous)
    value = 0.0

    if word in EQUALITY_WORDS:
        value = EQUALITY_WORDS[word]
    elif 'equal' in word:  # Equality-checking method names and identifiers.
        value = 3.2
    elif word in RELATED_WORDS:
        value = RELATED_WORDS[word]
    elif word in TRANSLATIONS:
        if word != 'рав' or raw[:1].isspace():
            value = TRANSLATIONS[word]
    elif s in OPERATORS:
        value = OPERATORS[s]
    elif len(s) >= 2 and set(s) == {'='}:
        value = 0.75 if len(s) == 2 else 0.60

    # Token boundaries and identifier spelling affect response strength.
    if word == 'equal' and s.startswith('_'):
        value = 5.7
    elif word == 'eq' and s.startswith('_'):
        value = 6.0 if s.isupper() else 4.5
    elif word == 'equ':
        value = 1.9 if raw[:1].isspace() else (
            1.6 if s[:1].isupper() else 0.56)
    elif word == 'qual':
        value = 1.3 if raw[:1].isspace() or s.startswith('_') else 3.4
        if not raw[:1].isspace() and previous.endswith('e'):
            value = 9.0  # Completing a split 'equal'.
    elif word == 'quality' and not raw[:1].isspace():
        value = 1.6
    elif s != word and word in {'what', 'same', 'better'}:
        value = {'what': 0.68, 'same': 0.58, 'better': 0.85}[word]

    if word == 'to' and prev in {'equal', 'equals'}:
        value = 3.74 if prev == 'equal' else 2.13
    elif word == 'than':
        if prev in {'less', 'greater'}:
            value = 1.06
        elif prev in {'lower', 'smaller', 'larger', 'bigger', 'fewer', 'other'}:
            value = 0.34
    elif word == 'of' and prev in {'equation', 'equality'}:
        value = 0.73 if prev == 'equation' else 1.9
    elif word in {'ation', 'ations'} and prev == 'equ':
        value = 1.15 if previous.strip()[:1].isupper() else 0.57
    elif word in {'ally', 'ating', 'aled'} and prev == 'equ':
        value = 3.2
    elif word == 'q' and prev in {'le', 'ge', 'ne', 'ce'}:
        value = 1.1  # Token-split LaTeX comparison commands.
    return (doc, raw), float(value)

programs.haiku:
"""Candidate v3: the word 'equal' and its relatives, 'to' after 'equal', and weaker comparison words."""

READS = ()

# Words for equality, by how strongly the component responds to them.
EQUAL_WORDS = {"equal": 7.0, "equals": 5.5, "equaled": 6.0}
EQUAL_FAMILY = {"equality": 3.0, "inequality": 2.0, "equally": 2.4, "equation": 1.4,
                "equations": 1.2, "eq": 2.5, "equ": 1.5, "qual": 1.0}
FOREIGN_EQUAL = {"等于": 3.8, "等": 1.7, "равно": 3.0, "gleich": 0.9}
COMPARISON = {"same", "==", "===", "!=", "what", "better", "greater"}

def clean(s):
    return s.strip().strip("_.()\"'").lower()

def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = clean(raw)
    if word in EQUAL_WORDS:
        return carry, EQUAL_WORDS[word]
    if word == "to" and len(prefix.token_strings) > 1 and clean(prefix.token_strings[-2]) in EQUAL_WORDS:
        return carry, 3.7
    if word in EQUAL_FAMILY:
        return carry, EQUAL_FAMILY[word]
    if raw.strip() in FOREIGN_EQUAL:
        return carry, FOREIGN_EQUAL[raw.strip()]
    if word in COMPARISON:
        return carry, 0.6
    return carry, 0.0

programs.luna:
"""Predict a sparse equality/comparison cue from the current token.

The rule is quiet for most tokens. It gives a large value to “equal”,
smaller values to equation terms, comparison marks and words, and to “what”.
"""

READS: tuple[str, ...] = ()

EQUATION_WORDS = {"equ", "equation", "equations", "equals", "gleich"}
COMPARISON_MARKS = {"==", "===", "≠", "<=", "同样", "均"}
COMPARISON_WORDS = {"same", "less", "better", "quality"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    previous = ""
    if len(prefix.token_strings) > 1:
        same_document = prefix.document_ids[-2] == prefix.document_ids[-1]
        if same_document:
            previous = prefix.token_strings[-2].strip().lower()

    if word == "equal":
        return None, 6.5
    if word in EQUATION_WORDS:
        return None, 1.4
    if word in COMPARISON_MARKS:
        return None, 1.0
    if word == "what":
        return None, 0.8
    if word == "than":
        return None, 0.7 if previous in {"less", "more", "greater"} else 0.0
    if word in COMPARISON_WORDS:
        return None, 0.7
    if word == "mean":
        return None, 0.4
    return None, 0.0

programs.sol:
"""A closing-delimiter signal, strongest for the end of parenthesized text.

Bracket and quote spellings determine the basic strength. Empty pairs and
newlines weaken it; several closers strengthen it. Remembering opening round
brackets lets longer enclosed phrases receive a stronger response. Escaped
LaTeX parentheses are math delimiters rather than ordinary phrase closures.
Longer word fragments just before a closer provide a small extra signal.
"""
READS = ()
OPENERS = '([{（［｛「『【《〈'
CLOSERS = ')]}）］｝」』】》〉'


def punctuation(s):
    t = s.strip()
    n = sum(s.count(c) for c in CLOSERS)
    lines = s.count('\n')
    space = s[:1].isspace()
    if n:
        if '）' in s:
            value = 2.3
        elif ')' in s:
            value = 1.5
        elif ']' in s or '］' in s:
            value = 1.1
        elif '}' in s or '｝' in s:
            value = 1.0
        else:
            value = 1.15
        value += 0.65 * min(n - 1, 3)
        if sum(s.count(c) for c in OPENERS) >= n:
            value -= 0.75
        elif t.endswith(tuple(OPENERS)):
            value -= 0.65
        if t[:1] in '.?!%':
            value += 0.8
        if t.endswith('.') and '(' not in s:
            value -= 0.5 if ')' in s else 0.3
        if t.endswith(('=', ':')) and ')' in s:
            value -= 0.45
        value += 0.2 * any(c in s for c in '\"\'”`')
        value += 0.3 * t.endswith('\\') + 0.15 * space
        if lines:
            penalty = 0.5 if ')' in s or '）' in s else 0.12
            value -= penalty * (0.4 if '(' in s else 1)
            value -= 0.18 * min(lines - 1, 2)
        return value
    if '”' in s or '»' in s:
        return 1.0 - 0.5 * space - 0.25 * min(lines, 2)
    if '"' in s:
        if space or any(c.isalpha() for c in t):
            return 0.0
        if t.startswith('\\"'):
            return 0.28
        if t[:1] not in '\".,?!' or t.count('"') > 1:
            return 0.0
        value = 0.73 - 0.45 * t.endswith(':') - 0.27 * t.endswith(',')
        return value - 0.4 * bool(lines)
    if '`' in s:
        return 0.6 if s.startswith('`') and s.count('`') == 1 and not lines else 0.02
    if t in ('$', '$$') and not space:
        return 0.4 * len(t)
    if t.startswith((';', '；')):
        return 0.4 if not lines else -0.05
    if t == '/' and not space and not lines:
        return 0.25
    if t == '>' and not space:
        return 0.42
    if t in ('etc', '等'):
        return 0.5
    if s in (' ,', ' .'):
        return 0.44 if ',' in s else 0.15
    return 0.0


def step(carry, prefix, upstream):
    doc, pos = prefix.document_ids[-1], prefix.position
    if carry is None or carry[0] != doc:
        stack, previous = [], ''
    else:
        _, stack, previous = carry
    s = prefix.token_strings[-1]
    span, escaped = None, False
    for i, c in enumerate(s):
        if c == '(':
            stack.append(pos)
        elif c == ')':
            if stack:
                span = pos - stack.pop()
            escaped = (i > 0 and s[i - 1] == '\\') or (
                i == 0 and previous.endswith('\\'))
    value = punctuation(s)
    if ')' in s:
        if escaped:
            value = 0.1
        elif span is not None and '(' not in s:
            if span <= 2:
                value -= 0.5
            elif span <= 3:
                value -= 0.1
            elif span <= 7:
                value += 0.15
            else:
                value += 0.4
            value -= 0.15 * previous.strip().isdigit()
            value += 0.1 * previous.strip().isalpha()
    if ')' in s and not escaped:
        word = previous.strip()
        if word.isalpha():
            value += 0.05 * min(len(word), 10)
            value += 0.1 * previous[:1].isspace()
        value -= 0.15
        value -= 0.25 * (s.count(')') > 1)
        value -= 0.2 * any(c in s for c in '"\'')
    if s == '"' and (not previous or previous.endswith('\n')):
        value = -0.1
    return (doc, stack, s), float(value)

programs.haiku:
"""Closing-delimiter detector (layer 0, MLP down_proj, component 329).

The component fires on the token that CLOSES a bracket, quotation or code span, and is
silent on almost everything else. Its strongest responses are to a ')' or '）' that ends a
parenthetical aside in running prose, e.g. "(born 1949 in Little Rock, Arkansas)".
Weaker: a ')' closing a one- or two-token group such as "(a)", ']' and '}' closers, and
closing quotation marks. Weakest: empty pairs "()", "[]", "{}", and LaTeX "\\)".

The program tracks open brackets per document (the stack resets at each document
boundary, as the model's attention does) and scores each token that contains a closer.
"""

READS = ()

PAIRS = {")": "(", "）": "（", "]": "[", "］": "［", "}": "{"}
OPENERS = set("([{（［")
CLOSE_QUOTES = set("”」』»》】")
CLOSING_PUNCT = {";": 0.4, "`": 0.6, ">": 0.4}


def closer_value(closer, n_inside, prev, empty):
    if empty:
        return 0.5  # "()", "[]", "{}" (opener and closer adjacent)
    if prev.endswith("\\"):
        return 0.7  # LaTeX \)
    if closer == "）":
        return 2.3
    if closer == ")":
        return 1.6 if n_inside >= 4 else 1.1  # long aside vs "(a)"-style
    return 1.1  # ']' and '}'


def step(carry, prefix, upstream):
    # carry: (open brackets as [opener, tokens since it opened], count of straight quotes)
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_doc:
        stack, quotes = [], 0
    else:
        stack, quotes = [list(x) for x in carry[0]], carry[1]
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    value = 0.0
    for ch in s:
        if ch in OPENERS:
            stack.append([ch, 0])
        elif ch in PAIRS:
            if stack and stack[-1][0] == PAIRS[ch]:
                _, n = stack.pop()
                value = closer_value(ch, n, prev, n <= 1)
            else:
                value = 1.1  # closes a bracket opened before this document window
    if value == 0.0:
        if any(ch in CLOSE_QUOTES for ch in s):
            value = 1.0
        elif s == '"':
            quotes += 1
            value = 0.9 if quotes % 2 == 0 else 0.45  # odd count: an opening quote
        elif s in CLOSING_PUNCT:
            value = CLOSING_PUNCT[s]
    for entry in stack:
        entry[1] += 1
    return ([tuple(x[:2]) for x in stack], quotes), value

programs.sol:
"""Approximate a negative response to Han content characters inside compounds.
Single characters are stronger than merged words; grammatical characters are
weaker. Recent kana strengthens the Han response (Japanese text). Hangul and
other writing get weaker script/word-shape baselines, with markup exceptions.
Individual-character and individual-word variation is deliberately omitted.
"""
READS = ()

GRAMMAR = frozenset(
    '的得了是在有我你您他她它咱俺们們和与與或而但就也都又很更最'
    '不没沒无無这這那哪其之着著过過把被让讓及为為于於以从從到给給'
    '吗嗎呢吧啊哦么麼因由若如则則并並且还還再才却卻亦乃所该該当當'
    '将將对對向按跟据據比即便既虽雖然此彼每各某另本'
)
NUMERALS = frozenset('零〇一二三四五六七八九十百千万萬亿億两兩几幾元')
MODIFIERS = frozenset(
    '大小中高低好坏壞新旧舊多少长長短上下左右前后後全半真早晚远遠近'
    '白黑红紅青黄黃绿綠蓝藍紫轻輕重超特老幼单双單雙总總'
)
COMMON_VERBS = frozenset('来來去出做说說看想要能会會可用等自')
SURNAMES = frozenset(
    '王李张張刘劉陈陳杨楊黄黃赵趙吴吳周徐孙孫马馬朱胡郭何高林罗羅'
    '郑鄭梁谢謝宋唐许許韩韓冯馮邓鄧曹彭曾萧蕭蔡潘田董袁'
)
# Common abstract, technical and nominalizing compound morphemes.
COMPOUND_MORPHEMES = frozenset(
    '性化者式型类類品法学學力系界业業员員度制製作理論论事道体體机機'
    '器科術术料定知育職职'
)
ENGLISH_FUNCTION = frozenset('''a an the of to in on at by for with from as and or
but if that this these those it its is are was were be been being am not no do
does did have has had he she we you they i me him her them my our your their who
which what when where why how can could will would shall should may might must
so than then there here each all any some such both either neither only also
very too'''.split())
KOREAN_PARTICLES = frozenset('을 를 에 은 는 이 가 와 과 로 도 만'.split())

# Previous-token kinds: other, single Han content/modifier, Han function,
# merged Han word, kana, digit. The extra shift is for single content characters.
OTHER, CHARACTER, FUNCTION, WORD, KANA, DIGIT = range(6)
CONTEXT = (0.0, -0.079, -0.036, -0.050, -0.031, 0.006)
CONTENT_CONTEXT = (0.0, -0.177, -0.077, -0.039, -0.024, 0.052)


def han(c):
    return '\u3400' <= c <= '\u4dbf' or '\u4e00' <= c <= '\u9fff'


def kana(c):
    return '\u3040' <= c <= '\u30ff'


def classify(word):
    """Return a context kind, baseline response, and single-content flag."""
    if not word:
        return OTHER, -0.003, False
    h = sum(han(c) for c in word)
    if h:
        if h != len(word):
            return WORD, 0.043, False
        if h > 1:
            return WORD, -0.023 if h == 2 else -0.015, False
        if word == '的':
            return FUNCTION, 0.087, False
        if word in GRAMMAR:
            return FUNCTION, -0.014, False
        if word in NUMERALS:
            return FUNCTION, -0.013, False
        if word in COMMON_VERBS:
            return FUNCTION, -0.047, False
        if word in MODIFIERS:
            return CHARACTER, -0.068, False
        if word in SURNAMES:
            return CHARACTER, -0.078, False
        return CHARACTER, -0.306 if word in COMPOUND_MORPHEMES else -0.154, True
    if any(kana(c) for c in word):
        return KANA, -0.009, False
    if all('\uac00' <= c <= '\ud7a3' for c in word):
        if word == '의':
            value = 0.023
        elif word in KOREAN_PARTICLES:
            value = -0.057
        else:
            value = -0.124 if len(word) == 1 else -0.033
        return OTHER, value, False
    if word.isdigit():
        return DIGIT, -0.001, False
    if '\ufffd' in word:
        return OTHER, -0.063, False
    if word in ('<think>', '</think>'):
        return OTHER, -0.170, False
    if word == '<tool_response>':
        return OTHER, -0.162, False
    if word == '</tool_call>':
        return OTHER, 0.065, False
    if word.startswith('<|') and word.endswith('|>'):
        return OTHER, 0.030, False
    if word.startswith('<') and word.endswith('>'):
        return OTHER, -0.040, False
    if word.isascii() and word.isalpha():
        if word.lower() in ENGLISH_FUNCTION:
            value = -0.003
        else:
            value = -0.007 - 0.0022 * min(len(word), 12)
            if word.isupper():
                value += 0.0045
        return OTHER, value, False
    if any('\u0400' <= c <= '\u052f' for c in word):
        return OTHER, -0.022, False
    return OTHER, -0.002 if not any(c.isalnum() for c in word) else -0.016, False


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, since_kana = OTHER, 1000
    else:
        _, previous, since_kana = carry
    kind, value, content = classify(word)
    if any(han(c) for c in word):
        value += CONTEXT[previous]
        if content:
            value += CONTENT_CONTEXT[previous]
        if token[0].isspace():
            value += 0.044
        if since_kana < 32:
            value -= 0.060
            value -= 0.071 if content else 0.133 if kind == WORD else 0.113
        # Year immediately following a number is a date suffix, not a compound.
        if word == '年' and previous == DIGIT:
            value = -0.015
    since_kana = 0 if kind == KANA else since_kana + 1
    return (doc, kind, since_kana), float(value)

programs.haiku:
"""Layer-0 MLP down_proj component 330: a "content character" detector.

It is negative at a Chinese character that carries word meaning (a noun, verb or adjective
morpheme such as 法 "law", 水 "water", 知 "know", 制 "system"), and close to zero on
grammatical function characters (的, 是, 在, 和, 了, 等, ...). It is more negative when
the character follows another CJK character, i.e. when it sits inside a word. Multi-
character Chinese tokens are mildly negative. Latin text, digits and punctuation sit at
a small constant negative baseline.

Predicted value: -0.20 for a content character, -0.35 when the previous token is also a
CJK-script token, -0.07 for a multi-character Chinese token, -0.01 otherwise.
"""

READS = ()

FUNCTION_CHARS = set("的了是在和与及或等有不也都就而但为以于对被把将会能要可我你他她它这那一")


def is_han(ch):
    return "一" <= ch <= "鿿"


def is_cjk_script(s):
    # Any CJK ideograph, kana or Hangul character, or a partial (undecodable) character.
    return "�" in s or any(
        "一" <= c <= "鿿" or "぀" <= c <= "ヿ" or "가" <= c <= "힯"
        for c in s
    )


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if len(token) == 1 and is_han(token):
        if token in FUNCTION_CHARS:
            return None, 0.0
        return None, (-0.35 if is_cjk_script(previous) else -0.20)
    if len(token) > 1 and any(is_han(c) for c in token):
        return None, -0.07
    return None, -0.01

programs.sol:
"""Recognize media/radio spellings and weaker broadcasting/measurement vocabulary.

This is a lexical detector, not a topic classifier: the isolated spelling pieces
'adi' and 'edia' also count, even inside unrelated words. The word 'media' is
weaker after 'social'. A few measurement phrases continue onto 'of' or the
final 'i' of 'radii'. All other tokens have zero response.
"""
READS = ()

# Spelling pieces found in radio, radiation, radius, media and medium.
# Their responses are estimated from training rows, not from token IDs.
FRAGMENTS = {
    'adi': -3.1, 'adio': -4.2, 'adia': -1.5, 'adian': -1.2,
