"""A lexical charge/load detector, with smaller spelling-fragment responses.

Charge and charges dominate, regardless of the sense of the word. Inflections
and discharge/recharge are weaker. Load/cargo words, Chinese load/charging
characters, and arg fragments are secondary triggers. Space and case matter:
a whole word beginning with a space differs from an identifier fragment.
The preposition in "charge of" also receives a response. No state is retained.
"""
READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('._/(-[')
    lower = word.lower()
    spaced = raw.startswith(' ')
    previous = ''
    if prefix.position and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().lower()
