        value = 7.1 if spaced else 6.0
    elif lower == 'charges':
        value = 7.4 if spaced else 3.7
    elif lower == 'charged':
        value = 4.7
    elif lower == 'charging':
        value = 4.5 if spaced else 3.1
    elif lower in {'discharge', 'recharge', 'charg', 'charger'}:
        value = 5.0 if word == 'Charg' else 3.1
    elif lower in {'discharged', 'chargers'}:
        value = 2.1
    # These are pieces of the same root when tokenization splits off 'ch'.
    elif lower in {'arges', 'arged'} or word == 'ARGE':
        value = 7.4
    elif lower == 'arging':
        value = 5.3
    elif lower == 'arge':
        value = 3.6
    elif lower == 'arger':
        value = 3.0
    elif lower in {'arga', 'argas', 'carg', 'carga', 'cargar'}:
        value = 2.3
    elif lower in {'load', 'loads'}:
        value = 1.4 if spaced or word[:1].isupper() else 1.1
    elif lower == 'loading':
        value = 0.8 if spaced else 0.5
    elif lower in {'loaded', 'loader', 'loaders'}:
        value = 0.4
    elif lower in {'arg', 'argin', 'argo'}:
        value = 1.9 if raw == 'arg' else 1.2
    elif lower in {'args', 'argc'}:
        value = 0.4 if word[:1].isupper() else 0.6
    elif lower == 'cargo':
        value = 1.0
    elif lower == 'burden':
        value = 0.7
    elif word == '荷':  # load, burden; also the lotus character
        value = 6.2
    elif word == '充电':  # electric charging
        value = 2.4
    elif lower == 'зар':  # Russian charge/pay root
        value = 1.7
    elif word == '收费':  # charging fees
        value = 1.8
    elif word in {'货', '貨'}:  # cargo / goods
        value = 0.9
    elif word == '充':  # fill / charge
        value = 1.2
    else:
        value = 0.0
    if lower == 'of' and previous in {'charge', 'charges', 'charging'}:
        value = 2.7 if previous == 'charge' else 2.4
    if previous == 'dis' and raw[:1].isalpha():
        if lower in {'charge', 'charged'}:
            value = 3.5 if lower == 'charge' else 3.0
    return None, value

