"""Word-level detector for the English word "charge" (and "load", "arg").

Layer-0 MLP feature that reads only the current token. Its activation is large on
forms of "charge" (electric or legal sense), moderate on "load" and "arg", and about
zero on everything else. Values are the mean activation per token form measured on
3,000 training rows (charge/charges ~7, charged/charging ~4.5, discharge/recharge
~3; load ~1.3, arg/Arg/ARG ~1.2-1.8, args ~0.6, cargo ~1.0).
"""

READS = ()

CHARGE = {
    "charge": 7.0, "charges": 7.5, "charged": 4.7, "charging": 4.5,
    "discharge": 3.0, "discharged": 2.2, "recharge": 3.4, "charger": 3.0,
    "charg": 2.9, "arge": 3.5, "arged": 7.3, "arging": 5.2, "arger": 3.5,
}
LOAD = {"load": 1.3, "loads": 1.3, "loading": 0.8, ".load": 1.1, "cargo": 1.0, "burden": 0.7}
ARG = {"arg": 1.3, "args": 0.6, "argin": 1.9}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    for table in (CHARGE, LOAD, ARG):
        if word in table:
            return carry, float(table[word])
    return carry, 0.0

