programs.haiku:
"""Component layers.0.mlp.down_proj:334 - a 'special-token and odd-character' detector.

It is near zero on ordinary text, and fires on a few specific tokens:
  * the role name `user` right after the chat marker `<|im_start|>` (about 1.1);
  * the no-break space U+00A0 (about 0.85);
  * Thai script characters (about 0.2), a weak tail;
  * stray single bytes that decode to U+FFFD, the replacement character (about 0.1).
Everything else predicts 0.
"""

import unicodedata

READS = ()

NBSP = " "
REPLACEMENT = "�"


def is_thai(text):
    return bool(text) and all(unicodedata.name(ch, "").startswith("THAI") for ch in text)


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = prefix.position
    tok = toks[t]
    if tok == "user" and t >= 1 and toks[t - 1] == "<|im_start|>":
        return carry, 1.1
    if tok == NBSP:
        return carry, 0.85
    if is_thai(tok):
        return carry, 0.2
    if tok == REPLACEMENT:
        return carry, 0.1
    return carry, 0.0

