def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    bare = token.lstrip(' \t\r\n._/-')
    word = bare.lower()
    size = len(word)
    value = 0.0
    if word.startswith('pro'):
        if size == 3:
            value = -4.8 - (0.8 if bare[0].isupper() else 0.0)
        elif size == 4:
            value = -4.8 if word[3] in 'bfvt' else -3.2
        elif size == 5:
            value = -3.4 if word.startswith('prot') else -2.6
            if word in ('proof', 'proud'):
                value = -1.2
        else:
            value = -1.25
            if word.startswith('process'):
                value = 0.0
            elif word.startswith(('proce', 'provis', 'provider')):
                value = -2.1
            elif word.startswith('profit'):
                value = -3.0
            elif word.startswith(('protec', 'propor', 'progres', 'promo')):
                value = -1.8
            elif word.startswith(('produc', 'projec', 'profess')):
                value = -0.95
        if token.startswith('.'):
            value -= 0.8
        elif token.startswith('_'):
            value -= 0.3
    elif word.startswith('про'):
        value = {3: -3.7, 4: -3.8, 5: -2.4}.get(size, -1.3)
    elif word.startswith('пр'):
        value = -2.6 if size == 2 else -0.5
    elif word.startswith(('impro', 'approv')):
        value = -0.9
    elif 'pro' in word:
        value = -0.3
    elif word.startswith(('pred', 'prevent', 'pref', 'prep', 'pret')):
        value = -0.65
    elif word in ('pre', 'pr', 'pri', 'pra'):
        value = -0.5
    return None, value

"""Approximate a negative detector for 'get' and retrieval expressions.

Most tokens produce zero. Get forms and code getters produce negatives,
with strength set by case, punctuation, name length, and two preceding tokens.
Related obtaining words get weaker negatives. Bytes/Boolean and DOM getters
are weaker exceptions. Context is reset at each document boundary.
"""
import re

READS = ()
GETTER = re.compile(r'^(?:get|Get|GET)(?:[A-Z_].*)?$')
RETRIEVAL_FUNCTIONS = {
    'getattr', 'getenv', 'getcwd', 'getitem', 'getline', 'getchar',
    'getch', 'getc', 'getopt', 'gettext', 'getpid', 'gettimeofday',
}
GET_FORMS = {
    'getting': -3.15, 'gets': -2.32, 'got': -1.2, 'gotten': -2.1,
    'getter': -2.5, 'getters': -2.5,
}
RELATED = {
    'obtain': -0.9, 'obtaining': -0.67, 'obtained': -0.33,
    'obtains': -0.5, 'fetch': -0.6, 'retrieve': -0.78,
    'retrieving': -0.7, 'retrieved': -0.4, 'retrieval': -0.7,
    '获取': -1.55, '得到': -0.62, '取得': -0.48, '获得': -0.32,
    'obtener': -1.1, 'bekommen': -1.0,
}
CODE_WORDS = {
    'function', 'def', 'fn', 'const', 'void', 'int', 'long', 'double',
    'string', 'return', 'await',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    older, previous = carry[1:] if carry and carry[0] == doc else ('', '')
    token = prefix.token_strings[-1]
    word = re.sub(r'^[\W_]+', '', token)
    low = word.lower()
    prev, prev2 = previous.strip().lower(), older.strip().lower()
    value = 0.0
    if low in GET_FORMS and (word.islower() or word.istitle() or word.isupper()):
        value = -4.05 if word == 'Gets' else GET_FORMS[low]
    elif low in RELATED:
        value = RELATED[low]
    elif low.startswith('получ'):
        value = -0.8
    elif low in RETRIEVAL_FUNCTIONS:
        value = -3.8
    elif word in {'charAt', 'findViewById'}:
        value = -2.0 if word == 'charAt' else -1.6
    elif GETTER.fullmatch(word):
        suffix = word[3:]
        if suffix:
            value = -5.1 + 0.15 * len(suffix)
            value += 0.35 * token.startswith('.') + 0.3 * word.startswith('Get')
            value -= 0.15 * token[0].isspace()
            value = min(-2.2, value)
            if suffix in {'Bytes', 'Boolean'} or (
                suffix.startswith('Element') and 'By' in suffix
            ):
                value = -2.5
        elif not token[0].isspace():
            if token.startswith('('):
                value = -4.55
            elif word == 'GET':
                value = -4.35
            elif token.startswith(('.', '_')):
                value = -5.45 if word == 'get' else -5.2
            elif word == 'Get':
                value = -4.55
            else:
                inside_word = token == word and previous and previous[-1].isalpha()
                value = -3.6 if inside_word else -5.45
        else:
            value = -3.9 if word == 'Get' else -4.2 if word == 'GET' else -4.0
            if word == 'get':
                if prev in {'you', 'we', 'will', "'ll", '’ll'}:
                    value = -2.75
                elif prev in {
                    'i', 'they', 'it', 'not', 'must', 'should', 'would', "'d", '’d'
                }:
                    value = -3.4
                elif prev == 'import':
                    value = -6.2
                elif prev in CODE_WORDS:
                    value = -5.6
                elif previous.strip() in {'=', ':=', '{', '>', '[]'}:
                    value = -4.8
                elif previous.isspace():
                    value = -4.8
                if prev in {"'t", '’t'}:
                    if prev2 in {'can', 'couldn'}:
                        value = -4.4
                    else:
                        value = -2.3 if prev2 == 'didn' else -3.4
                elif prev == 'did' or prev in {'not', 'you'} and prev2 == 'did':
                    value = -2.0
    return (doc, previous, token), float(value)

programs.luna:
"""Most tokens are silent; the main cue is English “get”, often in code too.

Its inflections and the weaker synonym “obtain” get smaller negative pulses.
Whole-word checks avoid accidental matches inside words like “together”.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.lower()

    # Match get as a word/root, but not inside ordinary words like together.
    for i in range(len(word) - 2):
        if word[i:i + 3] != "get":
            continue
        before = word[i - 1] if i else " "
        after = word[i + 3] if i + 3 < len(word) else " "
        original_after = token[i + 3] if i + 3 < len(token) else " "
        if before.isalpha():
            continue
        suffix = word[i + 3:]
        if suffix.startswith("ting"):
            return None, -3.1
        if suffix.startswith("s") and not suffix[1:2].isalpha():
            return None, -2.3
        if not after.isalpha() or (original_after.isalpha() and original_after.isupper()):
            return None, -4.2

    # “Obtain” is a milder, less frequent cue in the same acquisition family.
    for i in range(len(word) - 5):
        if word[i:i + 6] != "obtain":
            continue
        before = word[i - 1] if i else " "
        if before.isalpha():
            continue
        ending = word[i + 6:].rstrip(" \t\r\n.,!?;:'\"()[]{}")
        if ending in ("", "s", "ing"):
            return None, -0.65
        if ending == "ed":
            return None, -0.32

    # The irregular past tense is a weaker version of the same verb cue.
    stripped = word.strip(" \t\r\n.,!?;:'\"()[]{}")
    if stripped == "got":
        return None, -1.3
    return None, 0.0

programs.sol:
"""Approximate a mainly lexical English 'one'/'ones' feature.

Capitalization and token boundaries matter: word-internal lowercase fragments
respond less. Immediately preceding restrictive or choice words attenuate
'one'. 'Once', plural counting words, and selected translations of 'one' have
smaller responses. This is not a general detector of the quantity one: most
other tokens, including digits, receive zero. Small scattered lexical effects
are deliberately omitted in favor of a short explanation.
"""
READS = ()
RESTRICTIVE = {'only', 'exactly', 'least'}
CHOICE_WORDS = {'a', 'any', 'just', 'than', 'first'}
PLURAL_COUNTS = {
    'zeros': 0.54,
    'tens': 1.02,
    'hundreds': 0.30,
    'thousands': 0.14,
    'millions': 0.13,
    'billions': 0.08,
}
OTHER_LANGUAGES_ONE = {'uno', 'один', 'ワン', '하나'}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    previous = ''
    if (prefix.position > 0 and
            prefix.document_ids[-2] == prefix.document_ids[-1]):
        previous = prefix.token_strings[-2]
    embedded = (raw == token and previous and previous[-1].isalnum())
    lower = token.lower()
    prev_word = previous.strip().lower()

    if lower == 'one':
        if token == 'One':
            value = 2.20 if embedded else 2.43
        elif token == 'ONE':
            value = 0.60 if embedded else 1.90
        elif embedded:
            value = 0.49
        elif prev_word == 'no':
            value = 0.94
        elif prev_word in RESTRICTIVE:
            value = 1.39
        elif prev_word in CHOICE_WORDS:
            value = 1.78
        else:
            value = 2.20
    elif lower == 'ones':
        value = 0.75 if embedded else 3.13
    elif lower == 'once':
        value = 0.48 if embedded else (0.90 if token == 'Once' else 0.74)
    elif lower == '-one':
        value = 1.40
    elif lower.strip('._([“—') == 'one':
        value = 2.0
    elif lower in PLURAL_COUNTS and not embedded:
        value = PLURAL_COUNTS[lower]
    elif token in OTHER_LANGUAGES_ONE and (not embedded or not token.isascii()):
        value = 0.95
    else:
        value = 0.0
    return None, float(value)

programs.haiku:
"""Word-level detector for the English number word "one" (and "ones", "once").

Layer-0 MLP component layers.0.mlp.down_proj:338 writes a strong, token-specific
signal when the current token is the word "one": the numeral or pronoun, in any
capitalisation, with its leading space (" one", " One", "One"). It is weaker when the
word is glued to the previous text with no space ("one"), weaker still after
negation or limiting words ("no one", "only one", "at least one"), and strongest on
the plural " ones". "once" and the Spanish/Russian/Japanese equivalents fire more
weakly. It is nearly silent on every other token.

The program looks at the newest token and the one before it, and predicts the
typical activation for that situation.
"""

READS = ()

LIMITING_BEFORE = {"only", "least", "than", "just", "exactly", "third", "number"}
ONE_WORDS = {"one", "uno", "один", "ワン"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    spaced = token[:1] in (" ", "")
    if word == "ones":
        value = 3.0 if spaced else 0.8
    elif word == "once":
        value = 0.8
    elif word == "one":
        if not spaced and token == "one":
            value = 0.7          # lowercase, glued to the previous text
        elif previous == "no":
            value = 0.9          # "no one"
        elif previous in LIMITING_BEFORE:
            value = 1.4          # "only one", "at least one"
        elif token == " ONE":
            value = 1.9
        else:
            value = 2.2          # " one", " One", "One"
    elif word in ONE_WORDS:
        value = 0.9              # "uno", "один", "ワン": one in other languages
    else:
        value = 0.0
    return carry, float(value)

