}
FIRST_PUNCTUATION = {
    '.': .050, ',': .033, '+': .114, '/': .037, '-': -.036,
    '(': .004, ')': -.045, ':': .010, ';': .048, '"': .094,
    '[': .062, ']': .005, '{': .127, '}': -.011,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        run, pieces, position, previous, control_age = '', (), 0, '', 100
    else:
        _, run, pieces, position, previous, control_age = carry

    capitals = sum(c.isupper() for c in run)
    lowercase = sum(c.islower() for c in run)
    digits = sum(c.isdigit() for c in run)
    fragment_density = len(pieces) / max(1, sum(pieces))
    encoded = min(1., capitals / 25) * min(1., lowercase / 15)
    encoded *= min(1., digits / 3) * min(1., fragment_density / .5)
    early = math.exp(-position / 40)
    value = 0.
    if token in LINKING_PARTICLES:
        value = LINKING_PARTICLES[token] if position else 0.
        if (
            token == "の" and previous
            and previous[-1:] in "，。！？.!?,;:：；\n"
        ):
            value = -.06
    elif token == "而":
        value = .084 if previous[-1:].isalpha() else -.024
    elif len(token) == 1 and token in string.digits:
        i = int(token)
        value = DIGIT_BASE[i] + DIGIT_ENCODED[i] * encoded
        value += DIGIT_EARLY[i] * early
        if position == 0:
            value = DIGIT_FIRST[i]
    elif token == '+':
        value = -.011 + .75 * encoded + .057 * early
    elif token.startswith('+'):
        value = -.012 + .40 * encoded + .024 * early
    elif token == '/':
        value = .002 + .75 * encoded + .027 * early
    elif token.startswith('/'):
        value = -.002 + .25 * encoded + .007 * early
    elif token in ('\\n', '\\'):
        value = .004 + .34 * encoded + .025 * early
    elif token in (
        '"', '=', '==', '="', '=="', '"\n', '";', '",', '",\n'
    ):
        value = .011 + .28 * encoded + .009 * early
    elif token.isspace():
        if position == 0:
            value = .044 if token in ('\n', '\n\n') else 0.
            if token == ' ':
                value = .172
        elif len(run) > 50 and capitals > 10 and lowercase > 10:
            value = .30 * encoded
    # This pattern occurs in text containing non-whitespace control codes.
    if token == '\\' and control_age < 12 and run.isupper() and len(run) >= 2:
        value = .42
    if position == 0 and token in FIRST_PUNCTUATION:
        value = FIRST_PUNCTUATION[token]

    # Compact runs continue through line wrapping, but not ordinary spaces.
    if token and all(c in ALPHABET for c in token):
        run = (run + token)[-100:]
        pieces = (pieces + (len(token),))[-40:]
    elif (
        token in ('\n', '\\n', '\r\n')
        and len(run) > 20 and capitals > 3
        and lowercase > 3 and digits > 0
    ):
        pass
    else:
        run, pieces = '', ()
        for c in token:
            run = run + c if c in ALPHABET else ''
        if run:
            pieces = (len(run),)
    if any(ord(c) < 32 and c not in '\t\r\n' for c in token):
        control_age = 0
    else:
        control_age = min(100, control_age + 1)
    state = (doc, run, pieces, position + 1, token, control_age)
    return state, float(value)

"""A local demonstrative/reference-phrase predictor.

Lowercase 'this/these' and listed translated demonstratives are negative.
The next English word is positive for informational/abstract nouns and
consequence verbs; plural 'these' strengthens that response. Modifiers and
counts instead respond negatively. Smaller rules cover document starts,
Chinese classifiers, 'this kind/type/sort of', and PHP '$this->'.

These are coarse word-class estimates, not a full lexical model. Carry holds
only the last two tokens and resets whenever the document label changes.
"""
READS = ()

REFERENTS = set('''information data paper article book text section paragraph
message document report study review file script program code knowledge
info detail vocabulary course
result finding method approach process model function technique procedure
theory argument solution rule property principle equation formula strategy
system concept condition issue problem topic area feature parameter step
action decision resource guideline practice factor effect quality format
software interface package instruction setting expense cost fee reason fact
explanation relationship mechanism situation phenomenon'''.split())
NOUNS = set('''point question example way option thing case term number value
part line form event view statement expression application product tool
service work graph figure table website video page company object test
patient country material cell device field meeting idea link cookie'''.split())
TIME = set('''day week month year morning evening night season century
weekend summer winter spring autumn hour minute second'''.split())
MODIFIERS = set('''new old little same certain specific special important
other good bad large small free total entire whole single first last next
previous former current rather powerful short unique recent intriguing
remarkable prestigious historic stunning troubled simple unfortunate humble
very different'''.split())
AUXILIARIES = set('''is are was were be been can could will would should may
might must has have had does do did isn wasn'''.split())
VERBS = set('''means makes allows enables helps requires provides gives shows
suggests indicates implies explains demonstrates represents causes affects
leads works occurs happens tells involves transforms'''.split())
FOREIGN_THIS = set('''cet cette este esta estos estas questa questi queste
dieser diese dieses diesen diesem этот эта эти этого этой этому эту этим этих
acest această aceste данной данном هذه هذا này'''.split())
CHINESE_THIS = set('''这 這 此 这个 這個 这种 這種 这一 這一 这样的 這樣的'''.split())
CLASSIFIERS = set('''个 個 次 座 份 种 種 段 片 首 则 則 位 件 名 款 家 场 場 项 項 部 本
两 兩 三种 两个 兩個'''.split())
NUMBER_WORDS = 'one two three four five six seven eight nine ten'.split()
SELECTORS = {'this': 1., 'these': 1., 'following': 1.05,
             'such': .65, 'those': .65, 'above': .4, 'same': .4}


def reference(word, plural):
    root = word[:-3]+'y' if word.endswith('ies') else (
        word[:-1] if word.endswith('s') and not word.endswith('ss') else word)
    # Counts are negative, most strongly for 'two'.
    if word in NUMBER_WORDS:
        count = NUMBER_WORDS.index(word) + 1
        return 0. if count == 1 else -6.6 / count**2
    if root in {'kind', 'type', 'sort'} or word in {'particular', 'latter'}:
        return -1.6 if root in {'kind', 'particular', 'latter'} else -.8
    if word in MODIFIERS:
        return -.5 if plural else -.85
    # Pairs give singular-pointer and plural-pointer responses.
    for words, pair in [(REFERENTS, (.95, 1.75)), (NOUNS, (.5, 1.3)),
                        (TIME, (0., .5))]:
        if root in words:
            return pair[plural]
    if word in {'include', 'includes', 'included'}:
        return 2.7 if plural else 1.9
    if word in VERBS:
        return 1.2 if plural else .9
    if word in AUXILIARIES:
        return 1. if plural else .25
    if word in {'a', 'an', 'of'}:
        return -.7
    if word in {'and', 'or'}:
        return .3 if plural else -.25
    if word.endswith(('tion', 'sion', 'ment', 'ness', 'ity')):
        return .45
    if word.endswith(('al', 'ous', 'ive', 'ful', 'ic')):
        return 0.
    if len(word) < 4:
        return .5 if plural else .2
    return (.95 if plural else .4) if word.endswith('s') else .3


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    prev, before = ('', '') if fresh else carry[1:]
    token = prefix.token_strings[-1]
    w, p, b = token.strip(), prev.strip(), before.strip()
    lower, previous = w.lower(), p.lower()
    value = 0.
    if lower in {'this', 'these'}:
        if fresh:
            if lower == 'these':
                value = -1.62 if token.startswith(' ') else -2.13
            elif w[0].isupper():
                value = -2.65 if token.startswith(' ') else -3.78
            else:
                value = -3.7 if token.startswith(' ') else -3.48
        elif previous == 'following':
            value = -1.2
        elif w[0].isupper():
            value = .1 if token.startswith(' ') else -.05
        elif previous == 'in':
            value = -.75 if lower == 'this' else -.55
        elif previous in {'on', 'for', 'under', 'using', 'use', 'that', 'which'}:
            value = -.55
        else:
            value = -.4 if p.isalpha() and previous not in {
                'if', 'as', 'but', 'and', 'because'} else -.15
    elif w == '$this' or w.endswith('(this'):
        value = -.25
    elif lower in FOREIGN_THIS and (token.startswith(' ') or fresh):
        value = -.85
    elif lower in {'ce', 'ces', 'questo'} and token.startswith(' '):
        value = -.35
    elif w in CHINESE_THIS or w == 'この':
        value = -.5 if w in {'这', '这样的', '這樣的'} else -.95
    elif w in {'这些', '這些'}:
        value = -.45
    elif w in {'此次', '本次', '这次', '這次'}:
        value = -2.65 if w == '此次' else -1.8
    elif w.startswith(('这', '這')) and w[1:] in CLASSIFIERS:
        value = -1.25

    if previous in SELECTORS and lower not in {'this', 'these'}:
        if token.startswith(' ') and w.isascii() and w.isalpha():
            value = SELECTORS[previous] * reference(lower, previous == 'these')
            if (previous in {'this', 'these'} and p[0].isupper()
                    and prev.startswith(' ')):
                value += .15
            if not before and previous in {'this', 'these'}:
                if previous == 'this' and lower in AUXILIARIES:
                    value -= .4
                elif previous == 'these' and value > 0:
                    value += .65
            if w[0].isupper():
                value = .1
        elif w.startswith('->') and previous == 'this':
            value = -1.6
        elif w.startswith('.') and previous == 'this':
            value = -.2
        elif w.startswith(','):
            value = -.15 if previous == 'this' else .15 if previous == 'these' else 0.
    elif previous == '$this' and w.startswith('->'):
        value = -1.7
    elif lower == 'of':
        if b.lower() in {'this', 'these'}:
            value = -3.3 if previous in {'kind', 'kinds'} else (
                -2.5 if previous in {'type', 'types', 'sort', 'sorts'} else -.7)
        elif previous in {'kind', 'kinds', 'type', 'types', 'sort', 'sorts'}:
            value = -.6
    elif p in {'这', '這', '此', '在这', '这种', '这次'} and w in CLASSIFIERS:
        value = -1.4
    elif p in {'这些', '這些', '以下', '上述'}:
        value = .6 if any('\u4e00' <= c <= '\u9fff' for c in w) else 0.
    return (doc, token, prev), float(value)

programs.haiku:
"""Demonstrative determiners ("this", "these") and the word right after them.

Activation of down_proj unit 340 in layer 0 is sparse. Its main behaviour:
- A lowercase "this" or "these" used as a determiner in prose ("in this", "of these") is
  negative (about -0.5 to -0.8). After code punctuation ("$this", "= this") it is near 0.
- The first word after a demonstrative is positive: most after "These" and "these" (about
  +0.7 to +1.0), less after "This", "this", "those" (about +0.3), and about 1.5 times more
  when that word is plural (ends in "s"). Numbers and kind-words
  ("these two", "this kind") are negative instead.
- A demonstrative in another language (这个, 此次, この, este) is negative.
- "This" starting a document (after <|endoftext|>) is strongly negative.
- "of" after "kind(s)", "type(s)", "each", "both" is negative.
Everything else is predicted as 0.
"""

READS = ()

DEMONSTRATIVES = {"this", "these"}
FOREIGN_DEMONSTRATIVES = {"这个", "这种", "这些", "此次", "本次", "这", "這", "這個", "這些", "この", "este", "esta", "Este", "cette", "dieses", "dieser", "diesen"}
# how strongly the next word responds, by the demonstrative before it
AFTER_DEMONSTRATIVE = {"These": 1.0, "these": 0.7, "This": 0.5, "this": 0.3, "those": 0.3, "Those": 0.4, "following": 0.4}
NUMBER_OR_KIND_AFTER_THESE = {"two", "three", "kind", "type", "particular", "latter", "new"}
KIND_WORDS = {"kind", "kinds", "type", "types", "each", "such", "which", "both"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    new_doc = len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]
    prev = None if new_doc else prefix.token_strings[-2].strip()
    if cur in FOREIGN_DEMONSTRATIVES:
        return carry, -1.0
    if cur == "This" and (new_doc or prev == "<|endoftext|>"):
        return carry, -3.6
    if cur in DEMONSTRATIVES:
        # a demonstrative after a word (prose) is negative; after code punctuation it is not
        return carry, -0.55 if prev and prev[:1].isalpha() else -0.1
    if prev in AFTER_DEMONSTRATIVE and not new_doc:
        if cur in NUMBER_OR_KIND_AFTER_THESE:
            return carry, -1.2
        if cur.isalpha():
            return carry, AFTER_DEMONSTRATIVE[prev] * (1.5 if cur.endswith("s") else 1.0)
        return carry, 0.0
    if cur == "of" and prev in KIND_WORDS:
        return carry, -0.8
    if cur == "a" and prev in KIND_WORDS:
        return carry, -0.7
    if cur == "->" and prev == "this":
        return carry, -1.6
    return carry, 0.0

programs.luna:
"""Approximate a small layer-0 feature around demonstratives and PHP access."""

import re

READS = ()

NEGATIVE_WORDS = {"this", "these", "diese", "这样的"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    tail = "" if carry is None or carry[0] != document else carry[1]
    current_word = token.strip().casefold()

    value = 0.0
    if current_word in NEGATIVE_WORDS:
        value = -0.45
    elif token.strip() == "->" and re.search(r"\$this\s*$", tail):
        value = -1.5
    elif token[:1].isspace() and re.search(
        r"(?:^|[^\w])(?:this|these|following)\s*$", tail, re.IGNORECASE
    ):
        value = 0.75

    return (document, (tail + token)[-48:]), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:341: a bare-letter detector, mostly for maths and split words.

This layer-0 MLP output direction is near zero on most tokens (RMS 0.038 over all
positions). Most of its variance is token-specific and spread thinly over the vocabulary,
which a short program cannot capture. What it does respond to, strongly and in a readable
way, is a single bare letter (ASCII, no leading space) in a few settings. The program reads
only the current token and the one before it:

* the letter follows a superscript caret ("x^t", "^P"): strongly negative;
* the letter follows an opening math delimiter ("$ x", "\\( p"): positive, a math variable;
* the letter completes a split word whose earlier piece has accented or other non-ASCII
  letters ("ifø|l|ge", "hjæ|l|pe", "Å|M|Ø"): strongly negative, the typical
  Scandinavian/Hungarian/Central European fragment;
* any other bare letter: slightly negative;
* a reflexive pronoun ("himself", "itself", "themselves"): negative;
* a nationality or language adjective ("English", "French", "Italian"): slightly positive.

Every other token is predicted as 0. The values are least-squares fits on training text.
"""

READS = ()

MATH_OPENERS = {"$", " $", "$$", " $$", "\\(", " \\(", "\\[", " \\["}
REFLEXIVE = {" himself", " herself", " itself", " myself", " yourself", " themselves", " ourselves"}
NATIONALITY = {
    " English", " British", " European", " French", " Italian", " German", " Spanish",
    " Chinese", " Russian", " Dutch", " Danish", " Norwegian", " Swedish", " American",
    " Japanese", " Korean", " Portuguese", " Canadian", " Polish", " Indian",
}


def _bare_letter(text):
    return len(text) == 1 and text.isascii() and text.isalpha()


def _has_non_ascii(text):
    return any(ord(c) > 127 for c in text)


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if cur in REFLEXIVE:
        return carry, -0.08
    if cur in NATIONALITY:
        return carry, 0.04
    if not _bare_letter(cur):
        return carry, 0.0
    if prev == "^":
        return carry, -0.32
    if prev in MATH_OPENERS:
        return carry, 0.26
    if prev and prev[-1].isalpha() and _has_non_ascii(prev):
        return carry, -0.20
    return carry, -0.005

programs.sol:
"""Spelling-based protocol/interface responses, plus Chinese birth-order terms.

This is mainly a negative lexical detector for protocol and interface,
including plurals, common identifier prefixes and short spelling fragments.
Chinese agreement/interface words also respond. A separate strong response
covers the Chinese birth-order characters, including occurrences in names.
Other tokens are approximated by zero, not their small background activity.
"""

READS = ()

# Eldest (two forms), second, third, youngest.
BIRTH_ORDER = {'伯': -2.9, '孟': -0.8, '仲': -4.7, '叔': -3.3, '季': -0.8}
TRANSLATIONS = {'协议': -2.1, '協議': -2.1, '接口': -0.8, '介面': -0.8}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    stem = word.lstrip('._(/-')
    lower = stem.lower()
    if lower == 'protocol':
        if stem.isupper():
            value = -2.1
        elif stem == 'Protocol':
            value = -3.05 if token.startswith((' ', '.')) else -3.35
        elif token.startswith('('):
            value = -1.9
        elif token.startswith(('.', '_')):
            value = -2.6
        else:
            value = -2.75 if token.startswith(' ') else -3.7
    elif lower == 'protocols':
        value = -2.3 if token.startswith(' ') else -2.6
    elif lower in ('interface', 'interfaces'):
        value = -1.1 if token != stem or lower.endswith('s') else -1.25
    elif lower in ('prot', 'прот'):
        value = -1.0 if stem[:1].isupper() else -0.8
    elif lower == 'proto':
        value = -0.65 if word == 'proto' else -0.45
    elif lower in ('ocol', 'ocols'):
        value = -0.35 if lower == 'ocol' else -1.7
    else:
        value = BIRTH_ORDER.get(word, TRANSLATIONS.get(word, 0.0))
    return None, value

