"""A lexical cue for protocol/interface words and a few technical terms."""
READS = ()

TECH_TERMS = {"enum", "abstractmethod", "gui", "ssl"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()

    if token.startswith("protocols"):
