programs.sol:
"""A spelling-based approximation to a negative S/syllable detector.

It responds most to isolated s/S and short s-vowel fragments, less to
common complete words and consonant clusters. Case, repeated s, and word
and document boundaries adjust the response. Selected s-associated
spellings in other scripts and a few word families are included. A small part
of a response persists onto an immediately joined continuation token.
"""

READS = ()
PUNCTUATION = '.,;:!?/\\=-+_([{\"\'`<>*|#@&%'
# Following vowel: responses for two-letter, three-letter, longer fragments.
SYLLABLES = {
    'a': (-1.15, -0.71, -0.31),
    'e': (-0.19, -0.16, -0.07),
    'i': (-0.58, -0.44, -0.13),
    'o': (-0.94, -0.67, -0.24),
    'u': (-1.05, -0.56, -0.12),
    'y': (-0.76, -0.29, -0.14),
}
COMMON_WORDS = frozenset('''
see set say says said saw same some someone something sometimes such
six sub song sea source sources solve software support supply supplies
system single since sample select second send seven several sentence
sense series separate section search self serve safe save simple show
she should shall still start state step stop sure
'''.split())
# Productive s-initial word families with a stronger response.
S_WORD_FAMILIES = ('soci', 'super', 'supra', 'sustain', 'satisfact')


# Isolated letter: at a boundary, inside a word, at document start.
LETTERS = {
    's': (-0.64, -0.04, -1.50),
    'S': (-0.90, -0.05, -2.50),
    'с': (-0.77, -0.37, -1.10),  # Cyrillic es.
    'С': (-1.04, -0.57, -2.07),
    'σ': (-0.75, -0.75, -0.75),  # Greek sigma.
    'Σ': (-0.75, -0.75, -0.75),
}

def response(token, previous, first):
    word = token.lstrip().lstrip(PUNCTUATION)
    if not word:
        return 0.0
    low = word.lower()
    boundary = token != word or not previous.isalpha()
    if word[0] == 'S' and previous.islower():  # CamelCase.
        boundary = True
    repeated = previous in {'s', 'S', 'с', 'С', 'ſ'} and not boundary
    if token.lstrip().startswith(("'s", "'S")):
        return 0.0
    if word in LETTERS:
        value = LETTERS[word][2 if first else 0 if boundary else 1]
        if token == 's' and previous.isdigit():
            value = -0.37
        if token.lstrip().startswith('.S'):
            value = -0.35
        return value - (0.80 if repeated else 0.0)
    if low.startswith('s'):
        if low in {'sum', 'sin'}:
            return -0.25
        # September and common support/suggest/summary stems are weak.
        if low in COMMON_WORDS or low.startswith(('sept', 'supp', 'sugg', 'summ')):
            return 0.0
        if low.startswith('ss'):
            value = -0.50 if word.isupper() else -0.15
            return value - (0.90 if repeated else 0.0)
        if low == 'sigma':
            return -0.43
        if low.startswith(S_WORD_FAMILIES):
            return -0.75
        if low[1] not in SYLLABLES:
            return 0.0
        n = len(word)
        value = SYLLABLES[low[1]][min(n, 4) - 2]
        if n == 3:
            if low[2] in 'aeiu' and low[1] != 'o':
                value *= 0.40
            if low[2] in 'lr':  # Liquid consonants.
                value -= 0.14
        if word[0].isupper() and low[1] != 'o':
            value -= 0.17 if n <= 3 else 0.11
        acronym = word.isupper() and previous.isupper() and not boundary
        if not boundary:
            value *= 0.20 if acronym else 0.65
        if first:
            value *= 1.65
        return value - (0.55 if repeated and not acronym else 0.0)
    # Selected s-associated spellings: kana, Hangul, Mandarin, Arabic, Thai.
    if word in {'サ', 'ソ'}:
        return -1.80
    if word in {'す', 'です'}:
        return -0.55
    if word in {'さ', 'そ', '사', '서', '소', 'س', 'الس', 'ส'}:
        return -0.75
    if word in set('社苏萨桑沙索素丝笋') or word.startswith('社会'):
        return -0.80
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, old = ('', 0.0) if first else carry[1:]
    token = prefix.token_strings[-1]
    value = response(token, previous, first)
    joined = token[:1].isalpha() and previous.isalpha()
    prediction = value + (0.22 * old if joined else 0.0)
    return (doc, token[-1:] or previous, value), float(prediction)

programs.haiku:
"""layers.0.mlp.down_proj:344 is a word-initial "s" detector: it goes negative when a new word
begins with the s-sound syllable "so", "su" or "sa" (any capitalisation, e.g. " so", " So",
" SAN"), a bare capital "S", or a bare "s" starting a word. It is weaker on "si" and "se", on
a handful of common words starting "so"/"su"/"sa" (social, super, son, sun, sol, ...), and on
the s-sound letters of other scripts (Cyrillic с, Greek σ, katakana サ, hangul 사). Mid-word
s (plural "s", "'s", "-as") and ordinary words such as "some", "such", "same", "set" stay at 0.
