READS = ()

# Word-initial s-syllables, the strongest: "so", "su", "sa" (any case) and capital "S".
STRONG = {"so", "su", "sa"}
# A bare "s" or "si" as a word start: moderate.
MEDIUM = {"s", "si"}
# Short words that begin with so/su/sa and behave the same way.
S_WORDS = {"social", "society", "super", "son", "sol", "solar", "sun", "sus", "sand",
           "san", "sal", "sur", "sup", "sim", "sor", "soup", "soil", "sustainable"}
# s-sounding letters from other scripts: Cyrillic es, Greek sigma, katakana sa, hangul sa.
OTHER_SCRIPT = {"с", "σ", "サ", "사"}

def _core(text):
    return text.lstrip(" \n\t\r-./([\"“").lower()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    starts_word = (not token[:1].isalpha()) or (not before[-1:].isalnum())
    core = _core(token)
    if core in OTHER_SCRIPT:
        return carry, -0.8
    if not starts_word or token.startswith("'"):
        return carry, 0.0
    if core in STRONG or (core == "s" and token.strip() == "S"):
        return carry, -0.95
    if core in MEDIUM:
        return carry, -0.6
    if core == "se":
        return carry, -0.3
    if core in S_WORDS:
        return carry, -0.7
    return carry, 0.0

