READS = ()


def is_s_onset(token):
    # Ignore spaces and punctuation before the first letter, as in "(s" or "-s".
    for char in token:
        if char.isalpha():
            if char.lower() in {"s", "с", "σ", "ς"}:
                return True
            # Hangul syllables decompose into an initial consonant and a vowel.
            decomposed = unicodedata.normalize("NFD", char)
            return decomposed.startswith("ᄉ")
    return False


def step(carry, prefix, upstream):
    value = -0.15 if is_s_onset(prefix.token_strings[-1]) else -0.007
    return None, float(value)

