import re

READS = ()
# Closing marks, not their visually similar opening partners.
CLOSING_MARKS = {
    '》': 6.04, '〉': 1.5, '』': 1.55, '」': 0.76,
    '】': 0.93, '»': 0.26, '）': 0.13,
}


def closing_brace(token, line, previous):
    text = token.strip()
    before, after = text.split('}', 1)
    if '{' in before:
        return -0.12  # An empty pair is not an isolated closing brace.
    context = re.sub(r'^\s*[+-](?=\s|$)', '', line + before)
    context = re.sub(r'^\s*\d+(?:\t|\\t)', '', context)
    line_start = not re.sub(r'\\[tr]|\s', '', context)
    if line_start:
        if token.count('\n') > 1:
            return -0.06
        if ')' in after:
            return -0.04
        return 0.10
    if ';' in before:
        return 0.15  # A statement terminator before the block's closing brace.
    if previous.endswith('\\'):
        return 0.30  # An escaped brace.
    if '`' in previous and not previous.strip(' `'):
        return 0.05  # Code-formatting ticks immediately before the close.
    if previous.rstrip().endswith(']'):
        return 0.45  # A brace immediately after a closing list.
    if text.startswith('"') and '\n' in token:
        return 0.52 if text.count('}') > 1 else 0.85
    if '\n' in token:
        value = 0.65
    elif '\\' in after:
        value = 0.80
    elif '(' in after or '[' in after:
        value = 0.94
    elif '{' in after:
        value = 0.33 if '_' in after else 0.58
    elif any(c in after for c in ',;:.'):
        value = 0.52
    elif ')' in text or ']' in text:
        value = 0.64
    elif after and after != '}':
        value = 0.79
    else:
        value = 1.14 if text.count('}') == 1 else 1.38
    if token.startswith(' '):
        value -= 0.25
    if previous.isspace() or previous.rstrip().endswith(';'):
        value -= 0.25
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    line, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    if '}' in token:
        value = closing_brace(token, line, previous)
    elif ']' in token:
        if '[' in token.split(']', 1)[0]:
            value = -0.10
        elif '\n' in token:
            value = -0.10 if token.startswith(' ') else 0.08
        else:
            value = 0.34
            if token.startswith(' '):
                value -= 0.18
            if any(c in token for c in ',:;)'):
                value -= 0.15
            if "'" in token:
                value += 0.17
    else:
        value = 0.0
        for mark, strength in CLOSING_MARKS.items():
            if mark in token:
                value = strength if token == mark else strength * 0.5
                break
