"""Hunt-word detector for layer-0 MLP unit 351.

It fires on the spelled-out pieces of 'hunt' and 'punt' (hunt, hunting, hunter, punt...) and on
the German-style 'unt'/'unter' pieces (unt, Unta, unter, Unters...), the strongest cue.
Weaker cues: the word 'following'/'follows' and the fragments 'nt', 'unc', 'unk', 'unn', 'uns'.
Slightly negative on 'otherwise', 'sugar', 'generally'. Everything else predicts 0.
"""

READS = ()

UNT_PIECES = {"unt", "unts", "unta", "unter", "unters", "unting", "unte"}
HUNT_WORDS = {"hunt", "hunts", "hunted", "hunter", "hunters", "hunting", "punt", "punts"}
FOLLOW_WORDS = {"following", "follows", "follow"}
FRAGMENTS = {"nt", "unc", "unk", "unn", "uns"}
NEG_WORDS = {"otherwise", "sugar", "generally"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in UNT_PIECES:
        return None, 3.0
    if word in HUNT_WORDS:
        return None, 2.0
    if word in FOLLOW_WORDS:
        return None, 0.45
    if word in FRAGMENTS:
        return None, 0.4
    if word in NEG_WORDS:
        return None, -0.7
    return None, 0.0

programs.sol:
"""Approximate a mainly D-initial spelling feature with multilingual echoes.

Ignore punctuation introducing an identifier. Capital letters and short pieces
have stronger responses; long words, function words, and pieces continuing an
alphabetic word have weaker ones. Apostrophe-d is treated as a contraction.
D-like letters in other alphabets get a similar response. A small
set of Chinese translations of everyday English D-words is also recognized.
"""
import re

READS = ()
ROMANCE_OF = frozenset({'de', 'di'})
GERMAN_ARTICLES = frozenset({'der', 'die', 'das', 'den', 'dem'})
D_LETTERS = frozenset('дДδΔđĐďĎدדदদਦદదದደด')
D_KANA = frozenset('だでどダデド')
# Chinese translations of everyday English D-words.
CHINESE_D_WORDS = (
    '数据', '设备', '设计', '发展',  # data, device, design, development
    '不同', '下载', '深', '死',    # different, download, deep, dead
    '日', '下', '双', '部',       # day, down, double, department
)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != document
    previous = '' if fresh else carry[1]
    token = prefix.token_strings[-1]
    text = token.strip()
    state = (document, token[-1:])
    if text in {"'d", '’d'}:
        return state, -0.4
    word = re.sub(r'^[\W_]+', '', text)
    if not word:
        return state, 0.005
    first = word[0]
    glued = token == word and previous.isalpha()
    if word.startswith(CHINESE_D_WORDS):
        return state, 1.0
    if first in D_KANA:
        return state, 0.95
    if first not in 'dD':
        # Hangul syllables whose initial consonant is ㄷ (d/t).
        code = ord(first)
        hangul_d = 0xAC00 <= code <= 0xD7A3 and (code - 0xAC00) // 588 == 3
        if first in D_LETTERS or hangul_d:
            value = 1.4 - (0.6 if glued else 0.0)
        elif word.startswith('الد'):
            value = 3.0 if len(word) <= 6 else 1.5
        elif first in 'เแโใไ' and len(word) > 1 and word[1] == 'ด':
            value = 2.0
        else:
            value = 0.005
        return state, value
    length = len(word)
    lower = word.lower()
    if length == 1:
        value = 1.7 if first == 'D' else 1.4
    elif first == 'd' and text == word and lower in ROMANCE_OF:
        value = 0.7
    elif first == 'd' and text == word and lower in GERMAN_ARTICLES:
        value = 1.05
    elif lower == 'during':
        value = 0.75
    elif length <= 5:
        value = 1.5
    elif length <= 8:
        value = 1.25
    else:
        value = 1.15
    if length > 1 and first == 'D':
        value += 0.4
    if length > 1 and word[1].lower() not in 'aeiouy':
        value += 0.45 if length <= 3 else 0.15
    if text[:1] in './-':
        value += 0.3
    elif glued:
        value -= 0.35
    if fresh:
        value -= 0.5
    return state, float(value)

"""A negative detector for token spellings in the 'it' family.

Only the current token is read. Pronoun forms, short '-it' endings,
and initial 'it' fragments get negative values; longer extensions are
weaker. Case, leading whitespace and a few frequent spellings refine
these estimates. Terminal Cyrillic 'ит' is also recognized. This does
not model context-dependent variation or incidental non-'it' responses.
"""
import string

READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip().strip(string.punctuation)
    word = token.lower()
    cyrillic = 'ит' in word
    if cyrillic and word.endswith('ит'):
        word = word.replace('ит', 'it')
    boundary = bool(raw and raw[0].isspace())
    length = len(word)
    value = 0.0
    if word == 'it':
        if token.isupper():
            value = -2.45 if boundary else -3.85
        elif token == 'It':
            value = -1.60 if boundary else -1.82
        else:
            value = -1.37 if boundary else -2.95
            if 'ит' in token:
                value = -2.0
    elif word == 'its':
        value = -0.91 if boundary or token == 'Its' else -2.03
    # Two command names with unusually strong '-it' responses.
    elif word in ('git', 'exit'):
        value = -3.5
        if not boundary and raw == token:
            value -= 0.6
    # Common testing/initialization spellings respond less strongly.
    elif word in ('unit', 'init'):
        value = -0.68 if boundary else -1.35
    elif word.endswith('credit'):
        value = -2.8
    elif word.startswith(('with', 'write', 'white')):
        value = 0.0
    elif word.endswith(('ity', 'ities', 'ition', 'itions', 'itional')):
        value = 0.0
    elif word.startswith('itt'):
        value = -1.8
    elif word.startswith('it'):
        if word.startswith(('item', 'ity', 'ities')):
            value = 0.0
        elif word.startswith('iter'):
            value = -0.9
        else:
            value = -0.95 if length <= 4 else -0.45
    elif word.endswith('it'):
        if length == 3:
            value = -3.0
            if boundary and word.startswith(('b', 'm')):
                value = -2.05
            if not boundary:
                value -= 0.2
            if cyrillic:
                value = -1.7
        elif length == 4:
            value = -1.8
        elif length <= 6:
            value = -0.9
        else:
            value = -0.3
        # 'ai'/'ei' spell different vowel sounds from the short i of 'it'.
        if word.endswith(('ait', 'eit')):
            value *= 0.2
    elif word.endswith('its'):
        value = -1.6 if length <= 4 else -0.35
    elif 'itt' in word:
        value = -0.9 if length <= 9 else -0.3
        if word.startswith(('litt', 'writt', 'twitt')):
            value = -0.1
    elif 'it' in word:
        value = -0.4 if length <= 5 else -0.1
    return None, float(value)

