programs.sol:
"""Estimate the response to capitalized word pieces glued to punctuation.

A piece starting with a capital, but not a space, gets a positive response
following punctuation. Path/name separators are stronger than quotes and
parentheses; acronyms are weaker than title-case words. Word continuations
and line starts mostly suppress the response. At document starts its sign
reverses. Uncased writing, and lowercase words after a hash mark, have
smaller boundary responses.
"""

READS = ()
FUNCTION_WORDS = set("""
The This That These Those A An I We You He She It They In On At Of To From For
As By With And Or But Not Is Are Be Do If When What How Why Who Which
""".split())


def punctuation_strength(previous):
    """How strongly the preceding punctuation marks an attached word start."""
    c = previous[-1:]
    if not c:
        return 0.0
    if c == '#':
        return 1.8
    if c in '-/':
        return 0.55 if previous.endswith('</') else 1.4
    if c in '.@&':
        return 1.2
    if c == ':':
        return 1.3 if previous.endswith('::') else 0.9
    if c in '_–—…':
        return 1.05
    if c == '\\':
        return 0.85
    if c in '([{（':
        return 0.65 if previous.startswith(' ') or c in '{（' else 0.80
    if c in '\"\'`“”‘’«»„':
        return 0.66 if previous.startswith(' ') else 0.75
    if c in ',;=$':
        return 0.63
    if c in '，、。':
        return 0.45
    if c == '�':
        return 0.45
    if c == '*' and previous.endswith('**'):
        return 0.55
    return 0.76


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    state = (doc, s)
    if not s:
        return state, 0.0
    c = previous[-1:]
    newline = c in ('\n', '\r')
    if s[0].isupper():
        letters = ''.join(ch for ch in s if ch.isalpha())
        function_word = s in FUNCTION_WORDS
        single = len(letters) == 1
        acronym = not single and letters.isupper()
        if start:
            value = (-0.85 if function_word else -0.16 if single
                     else -0.08 if acronym else -0.50)
        elif newline:
            value = -0.02 if acronym else 0.0 if function_word else 0.06
        elif c.isalpha():
            if not c.isupper() and not c.islower():
                value = 0.10 if acronym else 0.33
            else:
                value = 0.0 if acronym else -0.04
        elif c.isdigit():
            value = 0.10 if acronym else 0.23
        elif c.isspace():
            value = 0.18 if acronym else 0.48
        else:
            value = punctuation_strength(previous)
            if acronym:
                value *= 0.43
            elif single:
                value *= 0.90
            elif function_word:
                value += 0.13
            elif not letters[1:].islower():
                value *= 0.80
        return state, value
    if s[0].isalpha() and not s[0].islower():
        if newline:
            return state, -0.13
        if not start and c and not c.isalnum() and not c.isspace():
            if c in '-/#':
                return state, 0.5
            if c in '(（・·':
                return state, 0.23
            return state, 0.07
    if s[0].islower() and not start:
        if c == '#':
            return state, 0.30
        if c.isdigit():
            return state, -0.09
        if newline:
            return state, -0.08
    return state, -0.004

programs.haiku:
"""Draft 4: a capitalised word glued onto punctuation fires; right after a special
boundary token (<|endoftext|> etc.) a capitalised word is pushed negative."""
READS = ()

CODE_JOINERS = set("#/-:@.")       # hashtags, paths, flags, scopes, mentions, dots
PROSE_OPENERS = set(",，、。\r")  # commas and CJK stops: weaker

def _is_symbol(ch):
    return not ch.isalnum() and not ch.isspace()

def _punct_level(prev):
    last = prev[-1]
    if last in CODE_JOINERS:
        return 1.2
    if last in PROSE_OPENERS:
        return 0.4
    return 0.7

def _style(word):
    if len(word) == 1:
        return 0.8      # single capital letter
    if any(c.islower() for c in word[1:]):
        return 1.0      # Title case word
    return 0.4          # ALL CAPS word

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if len(prefix.token_strings) < 2:
        return None, 0.0
    prev = prefix.token_strings[-2]
    if not cur[:1].isupper():
        return None, 0.0
    if prev.startswith("<|") and prev.endswith("|>"):
        return None, -0.6 if _style(cur) == 1.0 else -0.3
    if prefix.document_ids[-1] != prefix.document_ids[-2] or not prev or not _is_symbol(prev[-1]):
        return None, 0.0
    return None, _punct_level(prev) * _style(cur)

programs.sol:
"""Approximate a script- and format-boundary signal.

CJK tokens receive larger positive values when recent text is Latin script or
when they follow a break in a CJK run. Leaving CJK for ASCII or whitespace also
produces a positive response. Chat/document markers and a few named Chinese
grammatical classes have separate offsets. Most ordinary words remain near
zero; word-specific variation and incomplete UTF-8 pieces are only coarsely
approximated. State resets at each document boundary.
"""
import math
import unicodedata
from functools import lru_cache

READS = ()
CJK = {'han', 'kana', 'hangul'}
PERSONAL_PRONOUNS = set(
    '我 你 他 她 它 我们 你们 他们 她们 它们 我們 你們 他們 您'.split()
)
AND_CONNECTIVES = set('和 与 與 及 并 並 以及'.split())
NUMBER_WORDS = set('一二三四五六七八九十零')
CALENDAR_UNITS = set('年月日')

MARKERS = {
    '<think>': 0.45, '</think>': 0.0,
    '<tool_call>': -0.18, '</tool_call>': 0.03,
    '<tool_response>': -0.72, '</tool_response>': 0.74,
}
# Additions for the kind of character immediately preceding a CJK token.
ENTER = {
    'latin': 0.55, 'digit': 0.76, 'ascii_punct': 0.17,
    'unicode_punct': 0.05, 'newline': 0.33,
    'space': 0.09, 'byte': -0.19,
}


def character_kind(c):
    n = ord(c)
    if c == '\ufffd':
        return 'byte'
    if 0x3400 <= n <= 0x9fff or 0xf900 <= n <= 0xfaff:
        return 'han'
    if 0x3040 <= n <= 0x30ff:
        return 'kana'
    if 0xac00 <= n <= 0xd7af or 0x1100 <= n <= 0x11ff:
        return 'hangul'
    if c.isalpha():
        return 'latin' if 'LATIN' in unicodedata.name(c, '') else 'other'
    if c.isdigit():
        return 'digit'
    if c.isspace():
        return 'newline' if c == '\n' else 'space'
    return 'ascii_punct' if n < 128 else 'unicode_punct'


@lru_cache(maxsize=20000)
def describe(token):
    counts = {}
    last_letter = ''
    for c in token:
        kind = character_kind(c)
        if kind in CJK or kind in {'latin', 'other', 'digit', 'byte'}:
            counts[kind] = counts.get(kind, 0) + 1
        if c.isalpha():
            last_letter = kind
    if counts:
        kind = max(counts, key=counts.get)
    elif token.isspace():
        kind = 'newline' if '\n' in token else 'space'
    else:
        kind = 'ascii_punct' if token.isascii() else 'unicode_punct'
    end = character_kind(token[-1]) if token else 'space'
    return kind, end, last_letter


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, '', False, '')
    # 'before' is the previous token's final character class.
    _, previous, before, gap, last_script, role_header, history = carry
    # Recent script mix preserves the signal through short bilingual phrases.
    latin, cjk = history.count('L'), history.count('C')
    mix = latin / (latin + cjk + 2)
    token = prefix.token_strings[-1]
    kind, end, last_letter = describe(token)

    if token == '<|endoftext|>':
        value = {'han': 2.65, 'kana': 2.25}.get(last_script, 1.05)
    elif token == '<|im_start|>':
        value = {'han': -1.10, 'kana': -0.65, 'hangul': -0.65}.get(
            last_script, -0.15
        )
        if not previous:
            value = -0.28
    elif token == '<|im_end|>':
        if previous == '</tool_call>':
            value = 1.55
        elif previous == '</tool_response>':
            value = 1.80
        elif last_script in CJK:
            value = 0.85 if last_script == 'han' else 2.0
        else:
            value = 3.25 if before == 'ascii_punct' else 2.55
    elif token in MARKERS:
        value = MARKERS[token]
    elif previous == '<|im_start|>' and token in {'user', 'assistant', 'system'}:
        value = 1.0 if token == 'user' else 0.81
    elif kind in CJK:
        # Longer interruptions of a CJK run produce a larger return signal.
        distance = min(math.log1p(gap), 4.0)
        value = 0.016 + ENTER.get(before, 0.0) + 0.166 * distance
        value += 0.60 * mix + 1.12 * mix * mix
        if before in {'latin', 'ascii_punct', 'space'}:
            value += 0.21 * distance
        if token[:1].isspace():
            value += 0.28
        if kind != 'han':
            value *= 0.40 if kind == 'kana' else 0.50
        word = token.strip()
        if word in PERSONAL_PRONOUNS:
            value += 0.50
        elif word in AND_CONNECTIVES:
            value += 0.32
        elif word in NUMBER_WORDS:
            value += 0.35
        elif word in CALENDAR_UNITS:
            value += 0.23
        elif word == '第':  # Chinese ordinal prefix
            value += 0.75
        elif word == '在':  # Chinese 'in/at'
            value += 0.50
    elif kind in {'space', 'newline'}:
        if previous == '<|im_end|>':
            value = 1.45 if last_script == 'han' else 0.80
        elif role_header:
            value = 0.36 if previous == 'user' else 0.20
        elif previous in MARKERS:
            value = 0.48 if previous == '</think>' else 0.42
        elif before in CJK:
            value = 0.75 if before == 'han' else 0.40
        elif kind == 'newline' and before == 'unicode_punct':
            value = 0.45 if last_script == 'han' else 0.18
        else:
            value = 0.015
    elif kind in {'latin', 'digit', 'ascii_punct'} and before in CJK:
        if kind == 'ascii_punct':
            value = 0.57 if before == 'han' else 0.30
        elif kind == 'digit':
            value = 0.30 if before == 'han' else 0.13
        else:
            value = 0.24
    elif kind == 'unicode_punct' and last_script in CJK:
        s = token.strip()
        if s[:1] in {'“', '（'}:
            value = 0.57
        elif s[:1] in {'”', '）', '：', '；', '「', '」'}:
            value = 0.25
        elif s == '……':
            value = 0.80
        else:
            value = 0.06
    elif kind == 'byte':
        # Incomplete UTF-8 pieces: only a coarse word-boundary estimate.
        if token.startswith(' '):
            value = 0.65 if before in {'ascii_punct', 'newline'} else 0.35
        else:
            value = -0.10 if before == 'han' else 0.03
    else:
        value = 0.005

    header = previous == '<|im_start|>' and token in {'user', 'assistant', 'system'}
    if token.startswith('<') and token.endswith('>'):
        last_letter = ''
    last_script = last_letter or last_script
    gap = 0 if kind in CJK else min(gap + 1, 1000)
    family = 'C' if kind in CJK else 'L' if kind == 'latin' and not header else '-'
    if token.startswith('<') and token.endswith('>'):
        family = '-'
    history = (history + family)[-32:]
    return (doc, token, end, gap, last_script, header, history), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:359: a chat-turn-boundary and Chinese-text detector.

What the component does: it adds a push to the residual stream on a small set of
recognisable tokens, and is close to zero almost everywhere else. Its strongest responses:

  1. The end of a chat turn, <|im_end|>. It is strongest after an English sentence ends
     (. ? ! ) " ], about 3.3), medium after a tool tag (</tool_call>, </tool_response>,
