  4. The role words "user" (about 1.0) and "assistant" (about 0.8), which follow
     <|im_start|>, plus "</tool_response>" (0.8) and "<think>" (0.45).
  5. Chinese counters, time units and quantity words, 年 月 日 号 件 枚 名 万 亿 and
     中文 ("Chinese"): about 1.0 to 1.4, and 2.9 for 中文.
  6. A Chinese word that opens a Chinese run after non-Chinese text: about 0.5 (1.5 if it
     follows a space). Inside a run of Chinese characters it is almost zero.

Everything else is about zero. The levels are rough typical values read off about 2,500
rows of training text, not fitted coefficients. On held-out rows the program explains
about 40% of the variance; the rest is small, token-specific noise.

Main program: `step` looks at the newest token and the one before it (within the same
document), applies the first matching rule above, and returns its level. It carries no
state between positions.
"""

import unicodedata

READS = ()

# Sentence-final punctuation that ends an English sentence.
SENTENCE_END = {".", "?", "!", ")", '"', "'", "”", "’", "]", ":"}
TOOL_TAGS = {"</tool_call>", "</tool_response>"}
ROLE_WORDS = {"user": 1.0, "assistant": 0.8}
OTHER_WORDS = {"</tool_response>": 0.8, "<think>": 0.45}
COUNTERS = {
    "年": 1.3, "月": 1.1, "日": 0.9, "号": 1.1, "件": 1.4, "枚": 1.15,
    "名": 1.1, "万": 1.0, "亿": 1.3, "中文": 2.9,
}


def is_chinese(text):
    """True if `text` (ignoring leading spaces) is all CJK ideographs."""
    core = text.lstrip(" ")
    return len(core) > 0 and all("CJK" in unicodedata.name(c, "") for c in core)


def im_end_level(before):
    """How strongly <|im_end|> fires, given the token just before it."""
    if before is None:
        return 2.4
    if is_chinese(before):
        return 0.5
    if before.strip() and before.rstrip()[-1] in SENTENCE_END:
        return 3.3
    if before in TOOL_TAGS:
        return 1.6
    return 2.4


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2] if same_doc else None
    before_chinese = before is not None and is_chinese(before)

    if token == "<|im_end|>":
        return carry, im_end_level(before)
    if token == "<|endoftext|>":
        return carry, 2.6 if before_chinese else 1.1
    if token == "\n":
        if before == "<|im_end|>" or before_chinese:
            return carry, 0.8
        return carry, 0.1
    if token in ROLE_WORDS:
        return carry, ROLE_WORDS[token] if before == "<|im_start|>" else 0.0
    if token in OTHER_WORDS:
        return carry, OTHER_WORDS[token]
    if token in COUNTERS:
        return carry, COUNTERS[token]
    if is_chinese(token):
        if before_chinese:
            return carry, 0.03  # inside a Chinese run
        return carry, 1.5 if token.startswith(" ") else 0.5  # opening a Chinese run
    return carry, 0.0

