"""Make small, calibrated predictions at several text-format boundaries.

Document and conversation markers, line breaks, and chat role labels show a
weak association with this component. These are deliberately small nudges
around its average response, since the tokens alone do not determine it.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = 0.0155

    if token == "<|endoftext|>":
        value += 0.25
    elif token == "<|im_end|>":
        value += 0.50
    elif token == "<|im_start|>":
        value -= 0.05
    elif token == "<tool_response>":
        value -= 0.19
    elif token == "assistant":
