    elif word == "space" and any(x in context for x in (
        "empty", "parking", "enclosed", "hollow", "interior", "vertical",
        "physical", "ample", "occupied", "volume", "inside",
    )):
        value = -0.50
    elif word == "plot" and any(x in context for x in ("rectangular", "square")):
