programs.haiku:
"""layers.0.mlp.down_proj:361 - an indentation-width detector.

This component fires on long runs of blank space that a code or text file uses
for indentation or alignment: a token made only of spaces, tabs (a tab counts as
4 columns) or non-breaking spaces. Its activation rises roughly linearly with the
run's width from about 8 columns to about 28, peaks near 30, and fades for very
long runs. Long rule lines made of one repeated '-', '=' or '_' fire weaker, and
grow with their length. Everything else (words, punctuation, newlines) is ~0.

Plain-terms recipe: measure the width of the whitespace token just read, then
read the activation off a curve. Written as a piecewise-linear curve so the
knots can be read directly.
"""
import numpy as np

READS = ()

# Whitespace width in columns -> activation (piecewise linear).
WIDTH_KNOTS = [0, 7, 8, 12, 16, 20, 24, 28, 32, 40, 64, 100]
ACT_KNOTS = [0, 0.1, 1.0, 2.3, 3.6, 5.4, 6.6, 7.4, 7.3, 5.5, 3.5, 2.5]


def columns(token):
    """Columns of blank space in a token: space and nbsp 1, tab 4, newline 0."""
    return sum(4 if ch == "\t" else (1 if ch in " \xa0" else 0) for ch in token)


def is_blank(token):
    return len(token) > 0 and all(ch in " \t\xa0\r\n" for ch in token)


def is_rule(token):
    """A run of 9 or more of the same dash, equals sign or underscore."""
    return len(token) >= 9 and token[0] in "-=_" and len(set(token)) == 1


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if is_blank(token):
        return None, float(np.interp(columns(token), WIDTH_KNOTS, ACT_KNOTS))
    if is_rule(token):
        return None, min(4.0, 0.2 * (len(token) - 8))
    return None, 0.0

"""Predicts layers.0.mlp.down_proj:362, a component that goes negative on the
tokens of AI-assistant talk: chat-role tags, "AI language model" self-description,
the end of a reasoning block, and AI/chatbot/NLP vocabulary.

Strongest: the role word "assistant" right after "<|im_start|>", the tag that opens
the assistant's chat turn (about -2.5). Next: "model" in "AI language model"
(about -3.4), and "</think>" (about -1). Then "assistant" or "AI" in other places
(about -1.5). Milder: AI, model, bot, chat, prompt, response and similar English words
(about -0.5), and their Chinese counterparts (about -0.9). Everything else is near 0.
"""

READS = ()

ASSISTANT_WORDS = {"assistant", "Assistant"}

AI_WORDS = {
    "AI", "ai", "Ai", "model", "models", "Model", "Models", "_model", ".model", "/model",
    "bot", "bots", "Bot", "chatbot", "Chat", "chat", "LLM", "intelligence", "Intelligence",
    "language", "prompt", "prompts", "response", "responses", "Response", "conversation",
    "conversations", "generate", "generated", "Generate", "generator", "speech", "bert",
    "BERT", "transformer", "token", "PT", "GPT", "Chunks", "chunk", "transcription",
}

AI_WORDS_ZH = {"模型", "语言", "智能", "训练", "回复", "的回答", "型", "处理"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if tok in ASSISTANT_WORDS and prev == "<|im_start|>":
        value = -2.5
    elif tok == "model" and prev == "language":
        value = -3.4
    elif tok == "</think>":
        value = -1.0
    elif tok in ASSISTANT_WORDS or tok == "AI":
        value = -1.5
    elif tok in AI_WORDS:
        value = -0.5
    elif tok in AI_WORDS_ZH:
        value = -0.9
    else:
        value = 0.0
    return carry, value

