"""Respond to sentence-ending line breaks after long, unbroken prose.

Long lines strengthen the response, particularly at a blank line after a
period. Prior line breaks weaken blank-line responses. Bare single newlines
instead favor short lines and dialogue-role labels. Numeric and quoted
sentence endings are weakened, with an offset for ideographic full stops.
Other tokens are near zero. State resets between documents.
"""
READS = ()
ROLE_BONUS = {
    'user': 0.28, 'assistant': 0.09,
    '<tool_call>': 0.10, '<tool_response>': 0.17,
    '<|im_end|>': -0.11,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, tokens, chars, newlines, previous = 0, 0, 0, 0, ''
    else:
        _, position, tokens, chars, newlines, previous = carry
    text = prefix.token_strings[-1]
    count = text.count('\n')
    value = 0.001
    if count:
        head = text.split('\n', 1)[0].rstrip('\r')
        blank = count >= 2
        long_line = chars / (chars + 256)
        short_line = tokens / (tokens + 8)
        average = (position + 1) / (position + 1 + 32 * (newlines + 1))
        repeated = newlines / (newlines + 3)
        period = (head.count('.') == 1 or '。' in head) and not any(
            c.isalnum() for c in head)
        if period:
            if blank:
                value = 0.48 + 0.89 * long_line + 0.22 * average - 0.58 * repeated
            else:
                value = -0.24 + 0.72 * long_line + 0.36 * average - 0.12 * repeated
            if previous.strip().isdigit():
                value -= 0.08 if blank else 0.06
            if head.endswith(('"', "'", '”', '’')):
                value -= 0.21 if blank else 0.04
            if '。' in head:
                value += 0.10 if blank else 0.05
        elif head in ('?', '!', '？', '！'):
            value = (0.15 + 0.66 * long_line + 0.41 * average - 0.35 * repeated
                     if blank else -0.29 + 0.46 * long_line + 0.35 * average)
        elif head in ('', ' '):
            if blank:
                value = 0.08 + 0.40 * long_line - 0.20 * repeated
                if head == ' ':
                    value += 0.12 + 0.25 * long_line + 0.15 * average - 0.21 * repeated
                if previous == 'user':
                    value += 0.42
                value -= 0.13 * min(2, max(0, count - 2))
            elif head == '':
                value = 0.17 - 0.32 * short_line + 0.11 * repeated
                value += ROLE_BONUS.get(previous, 0.0)
            else:
                value = 0.04 - 0.16 * short_line + 0.33 * average
        tokens, chars = 0, 0
        newlines += count
    else:
        tokens += 1
        chars += len(text)
    return (doc, position + 1, tokens, chars, newlines, text), float(value)

