    "в", "с", "к", "на", "и", "для", "со",
}
PREFIXES = {
    "ob", "od", "ud", "pod", "po", "prz", "prze", "roz", "wy", "vy", "za", "zap", "pr", "pro",
    "wz", "przy", "nad", "bez", "ws", "wsp", "pos", "ost", "st", "zn", "kr", "up", "ro", "wo",
