    "ii", "ego", "ami", "ej", "ow", "ki", "ku", "nej", "om", "ie", "ých", "ní", "ym", "ou", "ech",
}


def is_slavic(text):
    """True if the token has a Slavic-only letter or any Cyrillic letter (U+0400 to U+04FF)."""
    return any(c in SLAVIC_LETTERS or "Ѐ" <= c <= "ӿ" for c in text)


def step(carry, prefix, upstream):
    # carry: (running rate of Slavic-letter tokens, document id of the previous token)
    level, last_doc = carry if carry is not None else (0.0, None)
    doc = prefix.document_ids[-1]
    if doc != last_doc:
        level = 0.0  # a new document starts with no Slavic context
    token = prefix.token_strings[-1]
    level = 0.95 * level + 0.05 * float(is_slavic(token))
    gate = min(1.0, level / 0.1)  # full strength once ~10% of recent tokens are Slavic
    if token == "<tool_call>":
        return (level, doc), 0.64
    word = token.strip()
    whole_word = token.startswith(" ")  # a token that begins a word
    if word in PREPOSITIONS and whole_word:
        value = -0.38
    elif word in PREFIXES:
        value = 0.65
    elif word in ENDINGS:
        value = -0.39
    else:
        value = 0.0
    return (level, doc), gate * value

programs.sol:
"""A dollar-sigil detector, with weaker hash and inline-code responses.

The strongest negative responses are single dollars attached to punctuation:
variable arguments, quoted interpolation, member access, and negation. Bare
or space-prefixed dollars depend on document/line position and simple evidence
of code versus math. Hashes are weaker at line starts or after indentation.
Doubled dollars and repeated hashes are not single sigils. Small, scattered
word-specific responses are mostly left at zero; no vocabulary table is used.
"""
import math

READS = ()


def identifier_fragment(text):
    return len(text) > 1 and text.isascii() and text.isidentifier()


def attached_dollar(before, spaced):
    """Strength of a dollar attached after punctuation in the same token."""
    if '->' in before or '::' in before:
        return -4.2
    if before.endswith('\\'):
        return -2.7 if '(' in before else (-0.96 if spaced else -1.48)
    if '!' in before:
        return -4.85 if '(' in before else -4.0
    if before[-1] in '([|#':
        return -4.2 if spaced else -3.8
    if before.endswith('"'):
        return -4.5
    if before[-1] in "'`":
        return -3.9 if spaced or '=' in before else -3.1
    if before.endswith('{'):
        return -3.5
    if before.endswith('}'):
        return -1.4
    if before.endswith(')'):
        return -1.7
    if before.endswith(']'):
        return -2.1
    if before.endswith('/'):
        return -3.1
    return -3.0 if before[-1] in '*-' else -2.7


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, previous, recent, php, variables = 0, '', '', False, False
    else:
        _, pos, previous, recent, php, variables = carry
    line_start = not recent.rsplit('\n', 1)[-1].strip()
    indent = previous.isspace()
    latex = '\\' in recent or '^' in recent
    text, spaced = s.strip(), s.startswith(' ')
    value = 0.0

    if s.endswith('$') and s.count('$') == 1:
        before = text[:-1]
        if before:
            value = attached_dollar(before, spaced)
        elif pos == 0:
            value = -3.35 if spaced else -4.21
        else:
            normal_end = bool(previous and (
                previous[-1].isalnum() or previous[-1] in ')}]'))
            value = (-1.15 + 0.12 * spaced - 0.3 * php - 0.51 * variables
                     + 0.13 * latex - 0.20 * line_start
                     - 2.05 / math.sqrt(pos + 1) + 0.40 * normal_end
                     - 0.40 * previous.endswith('\\'))
    elif text.endswith('${'):
        before = text[:-2]
        value = -0.3 if not before else (-1.5 if '"' in before else -1.2)
    elif text == '$$':
        value = 0.22 if spaced else -0.13
    elif text in ('$\\', '$('):
        value = -0.1 if spaced else -0.4
    elif text == '$.':
        value = 0.1
    elif '$' in text and identifier_fragment(text.rsplit('$', 1)[-1]):
        value = -0.85
    elif text.endswith('$_'):
        value = -1.2 if '(' in text else -0.7
    elif text.lower() in ('dollar', 'dollars'):
        value = -0.4
    elif s.count('#') == 1:
        before = text.split('#', 1)[0]
        if text == '#':
            if pos == 0:
                value = 0.38
            elif spaced:
                value = -0.58 + 0.38 * indent + 0.05 * line_start
            else:
                value = -0.6 + 0.33 * line_start
        elif before:
            value = -0.17 if before.endswith('&') else -0.8
    elif text.endswith('`') and s.count('`') == 1:
        value = -0.14 if text == '`' else -0.6
        if s == ' `':
            value = 0.07
    elif s == ' %':
        value = -0.33
    elif text.endswith('%') and '"' in text:
        value = -0.8

    # Observe whether an earlier dollar introduced an identifier, not a digit
    # or a single-letter mathematical variable. No later token is inspected.
    variables = variables or (previous.endswith('$') and identifier_fragment(s))
    php = php or s in ('php', '->', ' function', '::$', '<?php')
    return (doc, pos + 1, s, (recent + s)[-300:], php, variables), float(value)

programs.luna:
"""Approximate sparse negative responses to money and markup tokens.

Dollar signs inside an opening parenthesis or bracket get the strongest pulse;
other dollar forms and hash headings get smaller pulses.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    lower = token.lower()
    if "#" in token:
        return None, -0.5
    if "$$" in token:
        return None, 0.0
    if "$" in token:
        before = token.split("$", 1)[0].rstrip()
        if before.endswith(("(", "[")):
            return None, -4.0
        if "|$" in token:
            return None, -3.6
        if "+$" in token:
            return None, -2.5
        return None, -1.2
    if "dollar" in lower or "tiền" in lower:
        return None, -0.6
    return None, 0.0

programs.haiku:
"""Component layers.0.mlp.down_proj:367: a word detector for the Chinese character 连
("even", "in a row", "one after another") and the words built on it.

What it does: it fires on the token 连 / 連 (traditional) and on the "even" words
就连 / 甚至连 ("not even ..."), and on 面对 / 面對 ("face, confront"). It gives a
weaker positive value to other clause-opening Chinese words of the same kind: the
concessive "even / even if" words (甚至, 哪怕, 即使, 就算), the contrast and
result linkers (然而, 但却, 但也, 于是, 可是, 而, 可), and the determiners 那些,
那种, 这一切, 每, 最. Each of these gets a small positive value. A few words that
usually come before a verb (才, 先, 无, 面, 就, 尤其) get a small negative value.
Everything else gets 0.

Why: in the training text these tokens have the largest mean activation for this
component. It is a token-level feature; the context hardly matters. The values are
the average activations observed on training text (about 0.5 for 连, 0.7 for
就连, 0.6 for 面对, 0.2 for the weaker words).

Limits: this explains very little of the component's variance. Most of its variance
comes from many scattered tokens with small values, both signs, that have no shared
concept. A lookup table of the 1000 most informative tokens would explain about 14%
of held-out variance, and this program explains under 1%.
"""

READS = ()

EVEN_LIAN = {"连", "連"}
EVEN_COMPOUND = {"就连", "甚至连", "就連", "甚至連"}
FACE = {"面对", "面對"}
CONCESSIVE = {"甚至", "甚至是", "哪怕", "哪怕是", "即使", "就算"}
LINKERS = {"然而", "但却", "但也", "于是", "可是", "可", "而"}
DETERMINERS = {"那些", "那种", "这一切", "每", "最"}
BEFORE_VERB = {"才", "先", "无", "面", "就", "尤其"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in EVEN_COMPOUND:
        value = 0.7
    elif token in EVEN_LIAN:
        value = 0.5
    elif token in FACE:
        value = 0.6
    elif token in CONCESSIVE or token in LINKERS or token in DETERMINERS:
        value = 0.2
    elif token in BEFORE_VERB:
        value = -0.1
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A short-piece continuation signal for written u-vowels.

A word fragment ending in Latin u (including accents), Greek upsilon, or
Cyrillic у/ю usually makes the next short alphabetic piece strongly negative.
The pulse decays with the lengths of both pieces. Following o or i weakens
it; another u offsets and can reverse it. The qu spelling is weaker
than hu.
Punctuation, digits, and a u just inside the preceding fragment get smaller
pulses. Smaller pulses cover Arabic waw, Katakana u/yu, and u-vowel
signs in Indic scripts and Thai. The rule uses only the preceding token,
and resets at document boundaries. These rules summarize the negative
training examples just after u-containing fragments, not on u itself.
"""
import math
import unicodedata

READS = ()
U_VOWELS = ('u', 'υ', 'у', 'ю')


def unaccent(text):
    return ''.join(c for c in unicodedata.normalize('NFKD', text.lower())
                   if unicodedata.category(c) != 'Mn')


def other_u_strength(text):
    if not text:
        return 0.0
    name = unicodedata.name(text[-1], '')
    if 'VOWEL SIGN U' in name or name.endswith(('SARA U', 'SARA UU')):
        return 0.55
    if text[-1] in 'ウゥユュ':
        return 0.60
    if text[-1] == 'و':  # Arabic waw also writes a long u-vowel.
        return 0.27
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    current = unaccent(text) or text
    value = -0.001
    if carry is not None and carry[0] == doc and current:
        previous = carry[1]
        length_decay = math.exp(
            -0.365 * max(0, len(current) - 1)
            -0.17 * max(0, len(previous.strip()) - 2))
        amplitude = 0.0
        first = current[0]
        alphabet = unicodedata.name(first, '')
        is_letter_piece = first.isalpha() and any(
            script in alphabet for script in ('LATIN', 'GREEK', 'CYRILLIC'))
        if previous.endswith(U_VOWELS):
            if is_letter_piece:
                amplitude = -1.185
                if first in U_VOWELS:
                    amplitude += 1.44
                elif first == 'o':
                    amplitude += 0.735
                elif first == 'i':
                    amplitude += 0.21
                if previous.endswith('qu'):
                    amplitude += 0.405
                elif previous.endswith('hu'):
                    amplitude -= 0.86
                elif previous.endswith('ου'):
                    amplitude -= 0.675
                elif previous.endswith('ю'):
                    amplitude -= 0.195
            elif current.isdigit():
                amplitude = -0.45
            elif not first.isspace():
                amplitude = -0.20
            elif len(current) <= 3:
                amplitude = -0.155
        elif carry[2] and not first.isspace():
            amplitude = -carry[2]
        elif is_letter_piece:
            if len(previous) >= 2 and previous[-2] in U_VOWELS:
                amplitude = -0.14
            elif len(previous) >= 3 and previous[-3] in U_VOWELS:
                amplitude = -0.09
        value += amplitude * length_decay
    return (doc, current, other_u_strength(text)), float(value)

"""Sparse progress/advancement and Chinese name-syllable responses.

Progress vocabulary gets negative values, strongest for 'progress' and its
Chinese equivalents. Recognized movement/work phrases also respond on the
connecting word: 'working on', 'move forward', 'progress of', etc.
A separate positive branch recognizes selected Chinese syllables used in
foreign names or surnames, with weaker responses for short combinations.

Remember only the preceding word, resetting at document boundaries. Everything
unrecognized is zero. Longer-context variation and unrelated small lexical
effects are intentionally not modeled.
"""
import re

READS = ()

MOVE = {'move', 'moves', 'moved', 'moving'}
WORK = {'work', 'works', 'worked', 'working'}
CONTINUE = {'continue', 'continues', 'continued', 'continuing'}
PROCEED = {'proceed', 'proceeds', 'proceeded', 'proceeding'}
PROGRESS = {'progress', 'progresses', 'progressed', 'progressing'}

# Name/transliteration syllables, grouped by approximate response strength.
NAME_SYLLABLES = (
    (0.25, '里特米波利西迪蒂伯福托'),
    (0.5, '德克拉布卡尔爾雷普吉夫姚莱萊梅奥奧苏蘇曼'
          '魯鲁塔恩摩姆佛威麦麥菲韩韓'),
    (0.75, '亚亞尼罗羅诺諾胡麻洛娜丹馬薩弗艾沃'),
    (1.0, '马斯哈赫埃伊穆莫貝贝邓鄧杜戈'),
    (1.25, '阿巴萨帕耶玛瑪鲍鮑霍瓦'),
    (2.25, '烏乌'),
)
NAME_CHARACTERS = frozenset(''.join(chars for _, chars in NAME_SYLLABLES))


def english_word(token):
    words = re.findall(r'[a-z]+', token.lower())
    return words[-1] if len(words) == 1 else ''


def lexical(token, word):
    if word == 'progress':
        return -2.4 if token[:1] in '._' else -3.15
    if word in {'progressed', 'progressing'}:
        return -1.95
    if word == 'progresses':
        return -2.65
    if word in PROCEED:
        return -1.0
    if word in {'progression', 'progressively', 'momentum', 'meantime', 'midst'}:
        return -0.65
    if word in {'proceedings', 'progressive'}:
        return -0.25
    if word in {'ongoing', 'pursue', 'pursued', 'pursuing', 'pursuit',
                'advance', 'advances', 'advancement', 'advancements',
                'gradually', 'stalled', 'ahead', 'toward', 'towards'}:
        return -0.4
    if word in {'forward', 'forwards', 'moving', 'through', 'along', 'process'}:
        return -0.15
    if 'progress' in word:
        return -1.4
    if word == 'underway':
        return -1.3
    if word == 'tqdm':  # The progress-bar library.
        return -2.1
    # Selected progress/advancement vocabulary in Chinese, Korean, Japanese.
    for text, strength in (
        ('进度', -3.7), ('進度', -3.7), ('推进', -2.2), ('推進', -2.2),
        ('进展', -2.6), ('進展', -2.6), ('进程', -1.2), ('進程', -1.2),
        ('前进', -0.75), ('前進', -0.75), ('推动', -0.65), ('推動', -0.65),
        ('加快', -0.8), ('逐步', -0.8), ('进行', -0.35), ('進行', -0.55),
        ('开展', -0.55), ('開展', -0.55), ('阶段', -0.55), ('階段', -0.55),
        ('진행', -1.7), ('進め', -1.7),
    ):
        if text in token:
            return strength
    if len(token) == 1:
        for strength, characters in NAME_SYLLABLES:
            if token in characters:
                return strength
    if 2 <= len(token) <= 3 and len(set(token)) > 1:
        if all(ch in NAME_CHARACTERS for ch in token):
            return 0.6 if len(token) == 2 else 0.3
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = ''
    if carry is not None and carry[0] == document:
        _, previous = carry
    token = prefix.token_strings[-1].strip()
    word = english_word(token)
    value = lexical(token, word)
    if word == 'progress' and previous == 'in':
        value -= 0.6
    if previous in PROGRESS:
        if word in {'on', 'of', 'toward', 'towards', 'made'}:
            value = -2.0
        elif word in {'to', 'in', 'along'}:
            value = -1.0
    elif previous in WORK:
        if word == 'on':
            value = -1.4 if previous == 'working' else -1.0
        elif word in {'through', 'toward', 'towards', 'done'}:
            value = -0.65
        elif word == 'to':
            value = -0.2
    elif previous in MOVE:
        if word in {'on', 'forward', 'forwards', 'ahead', 'toward', 'towards', 'along'}:
            value = -1.1
        elif word in {'through', 'into'}:
            value = -0.6
        elif word == 'to':
            value = -0.4
    elif previous in PROCEED or previous in {'proceedings', 'progression'}:
        if word in {'on', 'to', 'of', 'through'}:
            value = -0.65
        elif word in {'with', 'from', 'by'}:
            value = -0.4
    elif previous in CONTINUE:
        if word in {'on', 'along', 'toward', 'towards'}:
            value = -0.8
        elif word == 'to':
            value = -0.25
    elif word == 'of' and previous in {'process', 'midst', 'pursuit', 'advance'}:
        value = -0.9 if previous == 'pursuit' else -0.45
    elif word in {'on', 'upon'} and previous.startswith('embark'):
        value = -0.65
    return (document, word), float(value)

