programs.sol:
"""Primarily a detector for 'in', with case and word-boundary sensitivity.

It is weaker after result-forms, presentation verbs, and '-ed' endings.
Other strong responses occur on circumflex-vowel fragments, repeated trailing
backslashes, and the membership sign. These are token-shape cross-reactions,
not additional claims about meaning. All remaining tokens predict zero.
The state stores just the previous token and resets at document boundaries.
"""
import re

READS = ()
CIRCUMFLEX = {'â': 4.15, 'ê': 2.15, 'î': 2.0, 'ô': 0.45, 'û': 0.58}
RESULT_FORMS = {'result', 'results', 'resulted', 'resulting'}
PRESENTATION = {
    'shown', 'described', 'discussed', 'expressed', 'illustrated',
    'demonstrated', 'outlined', 'explained', 'summarized', 'covered',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    stripped = token.strip()
    value = 0.0

    # A standalone 'in', or 'in' attached to opening punctuation.
    match = re.fullmatch(r'[\W_]*([iI][nN])', token)
    if match:
        word = match[1]
        boundary = token != word or not previous[-1:].isalpha()
        if word == 'In':
            value = 1.15 if not first else (1.8 if token == word else 1.58)
        elif word == 'IN':
            value = 0.92 if boundary else 0.20
        else:
            value = 0.88 if boundary else 0.19
            prior_word = previous.strip().lower()
            if prior_word in RESULT_FORMS:
                value = -0.04
            elif prior_word in PRESENTATION:
                value = 0.33
            elif prior_word.endswith('ed'):
                value = 0.75
        if first and token == ' in':
            value = 1.085

    # Circumflex letters give particularly large responses when split off
    # as short fragments, rather than inside a whole word.
    for char in stripped.lower():
        if char in CIRCUMFLEX:
            letters = sum(c.isalpha() for c in stripped)
            value = CIRCUMFLEX[char] * 0.52 ** ((letters - 1) ** 1.5)
            break
    if '∈' in token:
        value = 0.64
    slashes = len(token) - len(token.rstrip('\\'))
    if slashes >= 2:
        value = 1.15 if slashes % 2 == 0 else 0.60

    return (doc, token), float(value)

