programs.sol:
"""A lexical 'back / return / reverse' signal.

Back itself is strongly negative, its compounds and translations less so.
Come/fall back is weaker than go/look back. Some signal remains on the next
preposition or suffix, especially 'back of' and 'back' + 'ward'. Small lexical
spillovers to 'black' and 'front' are included. This is a word-based estimate,
not a claim to recover every contextual fluctuation of the component.
Capitalized Back at a document boundary gets a stronger value; unrecognized
tokens get zero. Only the current and immediately preceding token are read.
"""
READS = ()

WEAKER_BACK_PHRASES = {
    'come', 'comes', 'coming', 'came', 'fall', 'falls', 'falling', 'fell',
    'running', 'hold', 'holding', 'held', 'pay', 'pays', 'paid', 'laid', 'trace',
    'call', 'pull', 'pulled',
}
STRONGER_BACK_PHRASES = {'go', 'goes', 'going', 'went', 'look', 'looking', 'the'}


def word(token):
    return token.strip().lstrip('._-/()').lower()


def activation(token, previous):
    w = word(token)
    if w in {'back', 'backs', 'backed'}:
        if w == 'backs' and not token[:1].isspace():
            return -6.6
        if previous == 'dating':
            return -10.8
        if token.startswith('_'):
            return -5.2
        if previous in WEAKER_BACK_PHRASES:
            return -6.4
        if previous in STRONGER_BACK_PHRASES:
            return -9.4
        return -8.6 if token[:1].isspace() else -8.0
    if w == 'backing':
        return -7.2
    if w == 'backward':
        return -3.9
    if w == 'backwards':
        return -3.1
    if w.startswith('background') or w == 'backpack':
        return -1.6
    if w in {'backlight', 'backtrack'}:
        return -4.5
    if w.startswith('back') or w in {'comeback', 'traceback'}:
        return -2.7
    if w in {'callback', 'feedback', 'fallback', 'playback', 'rollback',
             'throwback', 'setback', 'drawback'}:
        if w == 'callback':
            return -1.1
        if w == 'feedback':
            return -2.0
        return -1.5
    if w == 'returned':
        return -2.2
    if w.startswith('returning'):
        return -1.9
    if w.startswith('return'):
        return -1.5
