    "<think>": -0.183,
    "</think>": -0.050,
    "<tool_call>": -0.075,
    "</tool_call>": -0.030,
    "<tool_response>": 0.123,
    "</tool_response>": 0.050,
    "<|im_start|>": 0.033,
    "<|im_end|>": -0.003,
    "<|endoftext|>": 0.012,
}


