    doc = prefix.document_ids[-1]
    previous, repeats = ("", 0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = CHAT.get(token, -0.002)
    if "^{" in token:
        value = -0.79
    elif "_{" in token:
        value = -0.65
        if previous.strip() in {"sum", "prod"}:
            value = -0.43
        elif previous.strip() in {"lim", "int", "ord"} or token.startswith("}"):
            value = -0.58
    elif token.startswith("{") and previous.endswith(("^", "_")):
        value = -0.82 if previous.endswith("^") else -0.69
        if previous.endswith(")^"):
            value = -0.97
    elif "^" in token:
        value = -0.27
        if "^^" in token:
            value = -0.08
        elif "(" in token or '"' in token:
            value = -0.47
        elif "\\" in token:
            value = -0.35
        elif token.startswith(" ") or any(c.isalpha() for c in token):
            value = -0.20
    elif "\r" in token:
        novelty = (1 + repeats) ** -0.7
        if token == "\r":
            value = 0.05 - 0.44 / (1 + repeats / 8)
        elif token.count("\n") >= 2:
            value = -0.03 - 0.34 * novelty
        elif any(c in token for c in ";{}()"):
            value = 0.04 - 0.30 * novelty
        else:
            value = -0.30 * novelty
    elif "((" in token and ")" not in token:
        value = -0.14 * min(3, token.count("(") - 1)
    elif "[[" in token:
        value = -0.12
    elif "[:-" in token:
        value = -0.40
    elif "{" in token and "\n" not in token:
        value = -0.075
        if any(mark in token for mark in ('"{', "'{")):
            value = -0.29
            if previous.endswith("f"):
                value = -0.41
            if "{}" in token:
                value = -0.12
        elif "{{" in token:
            value = -0.19
        elif token.startswith((" {", '{"')):
            value = -0.005
    repeats += int("\r" in token)
    return (doc, token, repeats), float(value)

