"""Approximate a negative response to apostrophe-based spelling.

Contractions, possessives, elisions (l', dell'), clipped endings (rockin'),
and single-letter prime/inverse notation get different strengths.
A small single-quote tracker suppresses closing quotes;
it resets at document boundaries and forgets spans after 60 tokens. Ordinary
text gets zero. A few detached pronunciation marks have secondary responses.
The constants are approximate training-set strengths, not token-ID lookups.
"""
import unicodedata as ud

READS = ()
APOSTROPHES = {"'", '’'}
CONTRACTIONS = {
    's': -1.08, 't': -1.19, 're': -2.11, 've': -2.33,
    'll': -2.12, 'm': -2.10, 'd': -2.55,
}
ELISION_STEMS = {
    'l', 'd', 'j', 'm', 'n', 's', 't', 'c', 'qu',
    'all', 'dall', 'dell', 'nell', 'sull', 'quest', 'com', 'anch', 'coll',
}
CLIPPED_STARTS = {'em', 'specially', 'cause', 'til', 'bout', 'twas'}


def contraction(suffix, word, curly):
    value = CONTRACTIONS[suffix]
    if curly:
        value -= 0.04 if suffix in {'d', 'll', 've'} else 0.27
    if suffix == 's':
        w = word.lower()
        if w == 'let':
            return -0.98 if curly else -0.56
        if word.isdigit():
            return -0.82 if curly else -0.57
        if w in {'he', 'she', 'there'}:
            value -= 0.67
        elif w in {'what', 'who', 'where', 'how'}:
            value -= 0.88
        elif w in {'it', 'that', 'here'}:
            value -= 0.26
    return value


def bare_apostrophe(word, quoted):
    w = word.lower()
    if quoted:
        return -0.13
    if len(word) == 1 and word.isupper():
        return -2.2                 # Capital-letter prime/inverse notation.
    if w in ELISION_STEMS:
        return -2.95 if len(w) <= 2 else -3.55
    if w in {'po', 'ol'}:
        return -5.25
    if w in {'o', 'un', 'tho', 'th', 'de', 'an'}:
        return -4.3
    if w in {'f', 'r'}:             # Common Python string prefixes.
        return -0.25
    if w == 'b':
        return -1.4
    if w.endswith('in') and len(w) > 3:
        return -4.55                # Dropping the g in an -ing ending.
    if word and word[-1].isalpha() and 'CJK' not in ud.name(word[-1], ''):
        return -2.6 if word[0].isupper() else -2.2
    return -1.0 if word.isdigit() else -0.12


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', False, 0)
    _, previous, word, quoted, age = carry
    age += 1
    quoted = quoted and age <= 60
    value = 0.0
    if s in APOSTROPHES:
        value = bare_apostrophe(word, quoted)
    elif len(s) > 1 and s[0] in APOSTROPHES:
        ending = s[1:]
        if ending in CONTRACTIONS:
            value = contraction(ending, word, s[0] == '’')
        elif ending.isalpha() and word:
            value = -0.9 if ending in {'un', 'une', 'est', 'être'} else -1.5
        elif s == "''":
            value = -0.72 if word else 0.0
    elif s == "\\'":
        value = -1.65 if word and not quoted else -0.13
    elif s == ';s':                 # Tail of an HTML-encoded apostrophe+s.
        value = -0.71
    elif s in {'ʻ', 'ʼ'}:      # Letter-modifying apostrophe signs.
        value = -2.5
    elif s == '᾽':
        value = -1.8
    elif s in {'ˈ', 'ː'}:           # IPA stress and length marks.
        value = -0.85
    elif s == '′':
        value = -1.11
    elif s == '`':
        value = -0.12
    elif s in {'‘', ' ‘'}:
        value = -0.7 if s == '‘' else -0.3
    elif s in {'ّ', '́'}:           # Detached shadda or acute accent.
        value = -2.2
    elif s and all(ud.category(c).startswith('M') for c in s):
        if all('ARABIC' in ud.name(c, '') for c in s):
            value = -1.1
    elif s == 'ſ':                  # Historical long s.
        value = -0.60
    elif s in {'ь', 'ъ'}:           # Cyrillic soft and hard signs.
        value = -0.35 if s == 'ь' else -0.55

    # Track single-quoted spans, ignoring word-internal or escaped apostrophes.
    for i, ch in enumerate(s):
        before = s[i-1] if i else (previous[-1:] or ' ')
        after = s[i+1:i+2]
        if ch == '‘':
            quoted, age = True, 0
        elif ch in APOSTROPHES and before != '\\':
            if quoted:
                if not (before.isalpha() and after.isalpha()):
                    quoted = False
            elif ch == "'" and (not before.isalnum() or (i == 0 and not word)):
                quoted, age = True, 0
            elif s in APOSTROPHES and previous.endswith(('(f', '(r')):
                quoted, age = True, 0
        word = (word + ch)[-40:] if ch.isalnum() else ''
        if quoted and age <= 4 and word.lower() in CLIPPED_STARTS:
            quoted = False
        if ch == '\n':
            quoted = False
    return (doc, s, word, quoted, age), float(value)

