CLASSES = (
    (0.56, SOCIAL | {'contemporary'}),
    (0.55, {'age'}),
    (0.43, {'global', 'globally', 'globe'}),
    (0.39, {'digital', 'digitally'}),
    (0.57, {'competitive', 'competitiveness'}),
    (0.33, {'increasing'}),
    (0.63, {'increasingly'}),
    (0.26, {'changing', '-changing'}),
    (0.52, {'evolving', '-evolving'}),
    (0.24, {'today', 'nowadays'}),
    (0.22, {'modern', 'modernity'}),
    (0.18, {'rapid', 'rapidly', 'fast', 'pace'}),
    (0.13, TECHNOLOGY | {'era', 'century', 'life', 'social', 'trends', 'planet'}),
