        (('社会', '社會', '发展', '發展', '现代化'), 0.47),
        (('全球', '不断', '不斷', '迅速', '趋势', '竞争', '向前', '前进'), 0.44),
        (('时代', '時代', '进步', '進步'), 0.93),
