TH word families give negative responses of different sizes: theme and
thin/thick are strongest, then short fragments, threads, and ordinary TH
words. Common grammatical/numerical TH words are exceptions. The rules also
cover theta/thaa, a few translations, ordinal suffixes, and a small echo on
the following word fragment or on 'of'/'you'. State resets at each document.
Unmatched tokens are normally zero; weak lexical responses are not modeled.
"""
import re
import unicodedata

READS = ()
QUIET_TH_WORDS = set('the this that these those they their theirs there then '
                     'therefore thus themselves through throughout three third '
                     'thirty'.split())


def response(s, previous, tail):
    if 'θ' in s or 'Θ' in s:
        greek = any('GREEK' in unicodedata.name(c, '') for c in tail)
        return -3.6 if greek else -2.2
    if s.strip() == 'الث':  # Arabic article followed by thaa.
        return -3.5
    if 'ث' in s:
        return -4.0 if s.strip() == 'ث' else (-2.0 if len(s.strip()) == 2 else 0.0)
    if 'þ' in s.lower():
        return -0.6
    # Related words: thickness, thorax, themes, thought, youth, and threats.
    if s in {'厚', '厚度', '薄', '胸'}:
        return {'厚': -3.5, '厚度': -2.6, '薄': -1.55, '胸': -2.0}[s]
    if '主题' in s or '主題' in s:
        return -2.6 / (1.0 + 0.15 * max(0, len(s) - 2))
    if s == 'テーマ':
        return -2.6
    if s in {'思', '思考', '思维', '思想', '理论', '威胁',
             '青年', '年轻', '青春'}:
        return -0.7
    pieces = re.findall(r'[^\W\d_]+', s)
    if not pieces or (s.startswith('<') and s.endswith('>')):
        return 0.0
    raw = pieces[0]
    w = raw.lower()
    capital = raw[0].isupper()
    joined = bool(tail) and s[0].isalpha()
    if w in QUIET_TH_WORDS:
        return 0.0
    if w.startswith('th') and not w.isascii():
        if w.startswith('thé'):
            return -2.0
        return -0.8 if w in {'thì', 'thành', 'thứ'} else -0.3
    if w in {'young', 'younger', 'youngest', 'youth'}:
        return -0.7
    if w in {'weather', 'leather'}:
        return -0.65
    if w == 'th':
        if tail and tail[-1].isdigit() and joined:
            return -0.23
        if previous.endswith(('<', '/')):
            return -3.2
        if capital:
            return -2.1 if raw.isupper() else -3.7
        return -1.3 if joined else -2.8
    if joined and not capital and w in {
        'ther', 'thon', 'thesis', 'thing', 'thin', 'ths'
    }:
        return -1.7 if w == 'thin' else (-0.75 if w == 'thing' else -0.6)
    if w == 'than':
        weak = previous.strip().lower() in {
            'less', 'greater', 'other', 'rather', 'fewer'
        }
        return -1.15 if weak else -1.95
    if w.startswith('thank'):
        return -1.0 if w.endswith('s') else (-1.45 if capital else -0.9)
    if w == 'thing':
        return -1.1 if previous.strip().lower() in {'same', 'bad', 'such'} else -1.6
    if w in {'therm', 'thesis', 'thee', 'thou', 'thy', 'thor', 'thr', 'thro'}:
        if w in {'therm', 'thesis'}:
            return -2.0
        if w in {'thor', 'thr', 'thro'}:
            return -3.2 if w == 'thr' else -2.6
        return -1.6
    if w == 'them':
        return -1.4 if capital else -0.4
    if w.startswith('theme'):
        return -3.7
    thin = w.startswith('thin') and not w.startswith(('think', 'thing'))
    if w.startswith('thick') or thin:
        return -3.0
    if w.startswith(('thread', 'thumb', 'throm')):
        return -3.0 if w == 'threading' or capital else -2.3
    if w.startswith('thom'):
        return -1.9
    if w.startswith(('theor', 'theat')):
        return -0.75
    if w.startswith('th'):
        return -2.8 if len(w) <= 3 else -1.3
    if w.startswith('although'):
        return -0.35
    if w in {'ith', 'yth', 'nth'}:
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is not None and carry[0] == doc:
        _, previous, tail, last_response = carry
    else:
        previous, tail, last_response = '', '', 0.0
    s = prefix.token_strings[-1]
    decoded = prefix.text_prefixes[-1][-1:] if '\ufffd' in s else s
    base = response(decoded, previous, tail)
    # Completed byte-split theta is stronger than the whole-character token.
    if '\ufffd' in s and decoded in {'θ', 'Θ'} and base == -2.2:
        base = -2.9
    echo = (s in {' of', ' you'} or (s.isalpha() and s[0].islower()))
    value = base + (0.15 * last_response if base == 0.0 and echo else 0.0)
    end_word = re.search(r'[^\W_]+$', s)
    if end_word:
        tail = ((tail if end_word.start() == 0 else '') + end_word[0])[-24:]
    else:
        tail = ''
    return (doc, s, tail, base), float(value)

programs.haiku:
"""Candidate 3: coordinating conjunctions ("and", "or" and their translations) push the
unit negative; "or" hardest. Strength depends on the word, and on the word before it."""
OR_TYPE = {"or": 1.2, "或": 1.6, "或者": 1.4, "oder": 1.0, "или": 1.0, "và": 1.3, "أو": 1.1, "및": 1.4, "veya": 1.0}
AND_TYPE = {"und": 0.85, "и": 0.65, "和": 0.8, "与": 0.55, "以及": 0.9, "及": 1.2, "や": 0.55,
            "et": 0.45, "and": 0.3, "&": 0.4, "と": 0.4, "dan": 0.4, "ve": 0.3,
            "e": 0.12, "y": 0.12, "og": 0.12, "ou": 0.2}
READS = ()

def _gate(prev, is_or):
    """How much the word before the conjunction matters."""
    p = prev.strip()
    if p.isalpha() and (p.endswith("s") or p.endswith("ing")):
        return 1.4                      # after a plural noun or -ing word: a list of things
    if p.isalpha() and p.endswith("ed"):
        return 0.5                      # after a past-tense verb: joins clauses
    if p.isalpha():
        return 1.0
    if p == "":
        return 0.3
    return 0.7 if is_or else 0.0        # after a comma, digit or symbol

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    is_or = word in OR_TYPE
    strength = OR_TYPE.get(word, AND_TYPE.get(word, 0.0))
    if strength == 0.0:
        return carry, 0.0
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    return carry, -strength * _gate(prev, is_or)

programs.luna:
"""Estimate a rare, negative response to coordinating words.

The clearest examples are English “and” and “or”: “or” tends to give a
larger response. A few equivalents in other languages show the same pattern.
"""

READS = ()

AND_WORDS = {"and", "и", "és", "serta", "&"}
OR_WORDS = {"or", "أو"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in OR_WORDS:
        return None, -0.65
    if word in AND_WORDS:
        return None, -0.35
    return None, 0.0
